function populateReportDropdowns() {

  const nameSelect = document.getElementById('report-name');

  const opSelect = document.getElementById('report-operator');

  if (!nameSelect || !opSelect) return;



  const curName = nameSelect.value;

  const curOp = opSelect.value;



  // Recipe / Image names

  const recSet = new Set();

  if (typeof RecipeDB !== 'undefined' && typeof RecipeDB.list === 'function') {

    RecipeDB.list().forEach(r => { if (r && r.name) recSet.add(r.name.trim()); });

  }

  const records = reportGetRecords();

  records.forEach(r => { if (r && r.imageName) recSet.add(r.imageName.trim()); });

  if (window.HMI_STATE?.recipe?.name) recSet.add(window.HMI_STATE.recipe.name.trim());



  const recList = Array.from(recSet).filter(Boolean).sort((a,b)=>a.localeCompare(b));

  nameSelect.innerHTML = '<option value="">All Images / Recipes</option>' +

    recList.map(name => `<option value="${reportEscape(name)}">${reportEscape(name)}</option>`).join('');

  if (curName && recList.includes(curName)) {

    nameSelect.value = curName;

  }



  // Operators

  const opSet = new Set();

  if (typeof RecipeDB !== 'undefined' && typeof RecipeDB.operators === 'function') {

    RecipeDB.operators().forEach(op => { if (op) opSet.add(op.trim()); });

  }

  records.forEach(r => { if (r && r.operator) opSet.add(r.operator.trim()); });

  if (window.HMI_STATE?.recipe?.operator) opSet.add(window.HMI_STATE.recipe.operator.trim());



  const opList = Array.from(opSet).filter(Boolean).sort((a,b)=>a.localeCompare(b));

  opSelect.innerHTML = '<option value="">All Operators</option>' +

    opList.map(op => `<option value="${reportEscape(op)}">${reportEscape(op)}</option>`).join('');

  if (curOp && opList.includes(curOp)) {

    opSelect.value = curOp;

  }

}

