function reportFilteredRecords(){

  const start=document.getElementById('report-start')?.value;

  const end=document.getElementById('report-end')?.value;

  const name=(document.getElementById('report-name')?.value||'').trim().toLowerCase();

  const operator=(document.getElementById('report-operator')?.value||'').trim().toLowerCase();

  const st=start?new Date(start).getTime():null, en=end?new Date(end).getTime():null;



  const filtered = reportGetRecords().filter(r=>{

    const t=new Date(r.dateTime || r.startTime || 0).getTime();

    if(st!==null && Number.isFinite(t) && t<st) return false;

    if(en!==null && Number.isFinite(t) && t>en) return false;

    if(name) {

      const recName = String(r.imageName||'').toLowerCase();

      if(!recName.includes(name) && !name.includes(recName)) return false;

    }

    if(operator) {

      const opName = String(r.operator||'').toLowerCase();

      if(!opName.includes(operator) && !operator.includes(opName)) return false;

    }

    return true;

  });



  // Sort by date/time

  filtered.sort((a, b) => {

    let tA = 0, tB = 0;

    if (reportSortField === 'startTime') {

      tA = new Date(a.startTime || a.dateTime || 0).getTime() || 0;

      tB = new Date(b.startTime || b.dateTime || 0).getTime() || 0;

    } else if (reportSortField === 'endTime') {

      tA = new Date(a.endTime || a.dateTime || 0).getTime() || 0;

      tB = new Date(b.endTime || b.dateTime || 0).getTime() || 0;

    } else {

      tA = new Date(a.dateTime || a.startTime || 0).getTime() || 0;

      tB = new Date(b.dateTime || b.startTime || 0).getTime() || 0;

    }

    return reportSortOrder === 'asc' ? tA - tB : tB - tA;

  });



  return filtered;

}

