async function getReportImages(recName) {

  const rec = (recName && window.RecipeDB ? RecipeDB.findByName(recName) : null) || window.HMI_STATE?.recipe || {};

  const result = { refImage: '', inspectImage: '', name: rec?.name || 'Recipe' };



  // 1. Reference Bag Artwork Image

  let refUrl = rec.imageDataUrl || rec.imageUrl || rec.frontImageUrl;

  if (!refUrl) {

    const lname = (rec.name || '').toLowerCase();

    if (lname.includes('thangamayil')) refUrl = '/images/thangamayil_25kg.jpg';

    else if (lname.includes('bullet')) refUrl = '/images/royal_bullet_26kg.jpg';

    else refUrl = '/images/veera_shivaji_26kg.jpg';

  }

  result.refImage = await urlToDataUrl(refUrl);



  // 2. Optical Inspection / Verification capture image

  const fullPreview = document.getElementById('full-cam-preview-img');

  const plateImg = document.getElementById('recipe-live-cam-img');

  let inspectUrl = '';

  if (fullPreview && fullPreview.src && !fullPreview.src.includes('placeholder') && !fullPreview.src.endsWith('/')) {

    inspectUrl = fullPreview.src;

  } else if (plateImg && plateImg.src && !plateImg.src.endsWith('/')) {

    inspectUrl = plateImg.src;

  }

  if (inspectUrl && inspectUrl !== refUrl) {

    if (inspectUrl.includes('/api/camera/stream')) inspectUrl = '/api/camera/snapshot';

    result.inspectImage = await urlToDataUrl(inspectUrl);

  }

  return result;

}

