async function exportReportPdf(){

  const rows = updateReportScreen();

  const totals = {'0-7': 0, '8-15': 0, '16-25': 0, '26-window': 0, unscored: 0, total: 0};

  rows.forEach(r => {

    totals['0-7'] += Number(r.c0_7) || 0;

    totals['8-15'] += Number(r.c8_15) || 0;

    totals['16-25'] += Number(r.c16_25) || 0;

    totals['26-window'] += Number(r.c26_w) || 0;

    totals.unscored += Number(r.unscored) || 0;

    totals.total += Number(r.total) || 0;

  });



  const first = rows[0] || {};

  const recName = first.imageName || document.getElementById('report-name')?.value || window.HMI_STATE?.recipe?.name || 'Veera Sivaji';

  const opName = first.operator || document.getElementById('report-operator')?.value || window.HMI_STATE?.recipe?.operator || 'Operator 1';

  const startTime = first.startTime ? reportFormatDate(first.startTime) : (jobState.startTime ? reportFormatDate(jobState.startTime) : (document.getElementById('report-disp-start')?.textContent || '—'));

  const endTime = first.endTime ? reportFormatDate(first.endTime) : (jobState.endTime ? reportFormatDate(jobState.endTime) : (document.getElementById('report-disp-end')?.textContent || '—'));

  const nowStr = new Date().toLocaleString();



  const matchedRec = (window.RecipeDB ? RecipeDB.findByName(recName) : null) || window.HMI_STATE?.recipe || {};

  const recBrand = matchedRec.brandTamil || '';

  const recProduct = matchedRec.product || 'Rice Packaging';

  const recWeight = (matchedRec.netWeight || 25) + ' Kg';

  const recLength = (matchedRec.repeatLength || 740) + ' mm';

  const recWidth = (matchedRec.width || 495) + ' mm';

  const recMaterial = matchedRec.material || 'BOPP';



  if (typeof showToast === 'function') showToast('PREPARING PDF REPORT WITH IMAGES...');

  const imgData = await getReportImages(recName);



  const win = window.open('', '_blank', 'width=1000,height=800');

  if (!win) { alert('Please allow pop-ups to export PDF.'); return; }



  let imgSection = '';

  if (imgData.refImage || imgData.inspectImage) {

    imgSection = `

      <div class="card" style="margin-top:14px; page-break-inside:avoid;">

        <div class="card-title">RECIPE ARTWORK &amp; OPTICAL INSPECTION IMAGES</div>

        <div style="display:flex; justify-content:center; align-items:center; gap:20px; padding:12px; background:#0b1118; border-radius:4px; margin-top:8px;">

          ${imgData.refImage ? `

          <div style="text-align:center; flex:1; max-width:320px;">

            <div style="font-size:10px; font-weight:800; color:#58a6ff; text-transform:uppercase; margin-bottom:4px;">Reference Bag Artwork</div>

            <img src="${imgData.refImage}" style="max-height:220px; max-width:100%; object-fit:contain; border-radius:4px; border:1px solid #30363d; display:block; margin:0 auto;" alt="Reference Bag Image">

            <div style="font-size:9.5px; color:#8b949e; margin-top:4px; font-family:monospace;">${reportEscape(recName)} &bull; ${reportEscape(recWeight)} &bull; ${reportEscape(recLength)} &times; ${reportEscape(recWidth)}</div>

          </div>` : ''}

          ${imgData.inspectImage ? `

          <div style="text-align:center; flex:1; max-width:320px;">

            <div style="font-size:10px; font-weight:800; color:#58a6ff; text-transform:uppercase; margin-bottom:4px;">Live Inspection Frame</div>

            <img src="${imgData.inspectImage}" style="max-height:220px; max-width:100%; object-fit:contain; border-radius:4px; border:1px solid #30363d; display:block; margin:0 auto;" alt="Inspection Frame">

            <div style="font-size:9.5px; color:#8b949e; margin-top:4px; font-family:monospace;">Camera Optical Registration Verification</div>

          </div>` : ''}

        </div>

      </div>`;

  }



  const tableRows = rows.length ? rows.map(r => `

    <tr>

      <td>${reportEscape(reportFormatDate(r.dateTime))}</td>

      <td style="color:#1a7f37; font-weight:700;">${reportEscape(r.startTime ? reportFormatDate(r.startTime) : '—')}</td>

      <td style="color:#cf222e; font-weight:700;">${reportEscape(r.endTime ? reportFormatDate(r.endTime) : '—')}</td>

      <td>${reportEscape(r.imageName || '—')}</td>

      <td>${reportEscape(r.operator || '—')}</td>

      <td style="text-align:center; color:#57606a;">${r.windowMm ? r.windowMm + ' mm' : (r.markWindow ? r.markWindow + ' mm' : '—')}</td>

      <td style="text-align:right;">${Number(r.c0_7)||0}</td>

      <td style="text-align:right;">${Number(r.c8_15)||0}</td>

      <td style="text-align:right;">${Number(r.c16_25)||0}</td>

      <td style="text-align:right;">${Number(r.c26_w)||0}</td>

      <td style="text-align:right; font-weight:bold; color:#1a7f37;">${Number(r.total)||0}</td>

    </tr>

  `).join('') : `<tr><td colspan="11" style="text-align:center; padding:16px; color:#666;">NO REPORT DATA FOR SELECTED FILTER</td></tr>`;



  win.document.write(`<!doctype html>

  <html>

