      .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #0969da; padding-bottom: 10px; margin-bottom: 12px; }

      .brand { font-size: 20px; font-weight: 900; color: #0969da; letter-spacing: 0.5px; }

      .brand small { display: block; font-size: 10.5px; font-weight: 600; color: #57606a; margin-top: 2px; }

      .meta-box { text-align: right; font-size: 10.5px; color: #57606a; }

      .card { border: 1px solid #d0d7de; border-radius: 6px; padding: 10px 12px; margin-bottom: 12px; background: #ffffff; }

      .card-title { font-size: 11px; font-weight: 800; color: #0969da; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px; border-bottom: 1px solid #eaeef2; padding-bottom: 4px; }

      .meta-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }

      .meta-item label { display: block; font-size: 9px; color: #6e7781; font-weight: 700; text-transform: uppercase; }

      .meta-item span { font-size: 12px; font-weight: 800; color: #24292f; }

      .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 6px; }

      .stat-card { background: #f6f8fa; border: 1px solid #d0d7de; border-radius: 6px; padding: 8px; text-align: center; }

      .stat-card.total { background: #dafbe1; border-color: #4ac26b; }

      .stat-val { font-size: 18px; font-weight: 900; color: #24292f; }

      .stat-card.total .stat-val { color: #1a7f37; }

      .stat-lbl { font-size: 9px; font-weight: 700; color: #57606a; margin-top: 2px; text-transform: uppercase; }

      table { width: 100%; border-collapse: collapse; margin-top: 8px; font-size: 10.5px; }

      th, td { border: 1px solid #d0d7de; padding: 5px 7px; text-align: left; }

      th { background: #f6f8fa; font-weight: 800; color: #24292f; }

      @media print {

        body { padding: 0; }

        .no-print { display: none; }

        -webkit-print-color-adjust: exact;

        print-color-adjust: exact;

      }

