function bindReport(){

  const screen=document.getElementById('report-screen');

  const open=()=>{

    screen?.classList.add('open');

    populateReportDropdowns();

    if(typeof fetchReportFromDB==='function') fetchReportFromDB();

    updateReportSortUI();

    updateReportScreen();

  };

  const addBtnAction = (id, fn) => {

    const el = document.getElementById(id);

    if (!el) return;

    el.addEventListener('click', fn);

    el.addEventListener('pointerup', fn);

  };

  addBtnAction('btn-open-report', open);

  addBtnAction('report-home', () => screen?.classList.remove('open'));

  addBtnAction('report-apply-filter', updateReportScreen);

  addBtnAction('report-clear-filter', () => {

    ['report-start','report-end','report-name','report-operator'].forEach(id=>{

      const e=document.getElementById(id);

      if(e) e.value='';

    });

    reportSortField = 'dateTime';

    reportSortOrder = 'desc';

    updateReportSortUI();

    updateReportScreen();

  });

  addBtnAction('report-export-xls', exportReportXls);

  addBtnAction('report-export-pdf', exportReportPdf);



  // Toggle sort order button in filter bar

  document.getElementById('report-sort-date-btn')?.addEventListener('click', (e) => {

    e.preventDefault();

    toggleReportDateSort('dateTime');

  });



  // Table headers click to sort

  document.getElementById('th-sort-date')?.addEventListener('click', () => toggleReportDateSort('dateTime'));

  document.getElementById('th-sort-start')?.addEventListener('click', () => toggleReportDateSort('startTime'));

  document.getElementById('th-sort-end')?.addEventListener('click', () => toggleReportDateSort('endTime'));



  // Dropdown changes filter automatically

  document.getElementById('report-name')?.addEventListener('change', updateReportScreen);

  document.getElementById('report-operator')?.addEventListener('change', updateReportScreen);



  // Open calendar on click or tap anywhere on the input or its container

  ['report-start', 'report-end'].forEach(id => {

    const el = document.getElementById(id);

    if (!el) return;

    const triggerPicker = () => {

      try {

        if (typeof el.showPicker === 'function') {

          el.showPicker();

        }

      } catch (err) {}

    };

    el.addEventListener('click', triggerPicker);

    el.parentElement?.addEventListener('click', (e) => {

      if (e.target !== el) {

        el.focus();

        triggerPicker();

      }

    });

  });



  populateReportDropdowns();

  updateReportSortUI();

}

