code_full:
function bindNavigation() {

  const tabs = document.querySelectorAll('.nav-tab');

  tabs.forEach(tab => {

    tab.addEventListener('click', () => {

      tabs.forEach(t => t.classList.remove('active'));

      document.querySelectorAll('.screen-panel').forEach(p => p.classList.remove('active'));

      tab.classList.add('active');

      const targetId = tab.dataset.target;

      const targetEl = document.getElementById(targetId);

      if (targetEl) targetEl.classList.add('active');

      // Any normal navigation into the recipe calibration page starts a fresh

      // edit transaction as well (not only the CALIBRATE quick button).

      if (targetId === 'screen-recipe') {

        if (typeof window.beginRecipeEdit === 'function') window.beginRecipeEdit();

      }

      if (targetId === 'screen-cam') {

        if (typeof window.fitCamStage === 'function') requestAnimationFrame(window.fitCamStage);

      }

    });

  });



  // MAIN CALIBRATE button (btn-quick-new): open the complete recipe/calibration form directly.

  // Use a dedicated handler instead of relying on nav-tab state, so the touchscreen

  // button works even when the current panel/nav state is unusual.

  const quickCalBtn = document.getElementById('btn-quick-new');

  const openRecipeCalibrationForm = () => {

    const panel = document.getElementById('screen-recipe');

    if (!panel) return;

    // Start a new edit transaction. HOME will restore this exact snapshot;

    // SAVE & EXIT will commit the current HMI_STATE.recipe.

    document.querySelectorAll('.screen-panel').forEach(p => p.classList.remove('active'));

    document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));

    panel.classList.add('active');

    document.querySelector('.nav-tab[data-target="screen-recipe"]')?.classList.add('active');

    if (typeof window.beginRecipeEdit === 'function') window.beginRecipeEdit();

  };

  if (quickCalBtn) {

    quickCalBtn.onclick = () => openProtectedNumericPassword('recipecal_password','RECIPE CALIBRATION (PASSWORD: 4444)');

    quickCalBtn.setAttribute('type', 'button');

    quickCalBtn.setAttribute('aria-label', 'Open recipe calibration');

  }

  window.openRecipeCalibrationForm = openRecipeCalibrationForm;



  // The recipe action buttons use direct onclick handlers so they work reliably

  // on both mouse and touchscreen input. Do not stack pointerup listeners.

  const homeBtn = document.getElementById('btn-discard-recipe');

  const saveBtn = document.getElementById('btn-save-recipe');

  const delBtn = document.getElementById('btn-delete-recipe');

  if (homeBtn) {

    homeBtn.type = 'button';

    homeBtn.onclick = function(e) { e.preventDefault(); e.stopPropagation(); goHomeFromRecipeCalibration(); };

    homeBtn.setAttribute('aria-label', 'HOME - discard recipe changes');

  }

  if (saveBtn) {

    saveBtn.type = 'button';

    saveBtn.onclick = function(e) { e.preventDefault(); e.stopPropagation(); saveRecipeCalibrationAndGoHome(); };

    saveBtn.setAttribute('aria-label', 'SAVE & EXIT - save recipe changes');

  }

  if (delBtn) {

    delBtn.type = 'button';

    delBtn.onclick = function(e) {

      e.preventDefault(); e.stopPropagation();

      if (typeof window.deleteRecipeCalibration === 'function') window.deleteRecipeCalibration();

    };

    delBtn.setAttribute('aria-label', 'DELETE RECIPE - remove recipe from database');

  }



  // Topbar quick actions

  const topbarNewPage = document.getElementById('topbar-new-page');

  if (topbarNewPage) {

    topbarNewPage.addEventListener('click', () => {

      const recipeTab = document.querySelector('.nav-tab[data-target="screen-recipe"]');

      if (recipeTab) recipeTab.click();

    });

  }



  const topbarSave = document.getElementById('topbar-save');

  const recipeSave = document.getElementById('btn-save-recipe');

  if (topbarSave && recipeSave) {

    topbarSave.addEventListener('click', () => {

      recipeSave.click();

    });

  }

}

