function initRuler99Ticks() {

  const g = document.getElementById('svg-ticks');

  if (!g) return;

  g.innerHTML = '';



  const totalLines = 99;

  const svgWidth = 350;

  const step = svgWidth / (totalLines - 1);

  const centerIdx = 49; // 50th line is center (index 49: 0..98)



  const halfWindowMm = HMI_STATE.recipe.markWindow / 2;

  const tickOffset = Math.round((halfWindowMm / 50) * 49);

  const windowLeftIdx = Math.max(0, centerIdx - tickOffset);

  const windowRightIdx = Math.min(totalLines - 1, centerIdx + tickOffset);



  for (let i = 0; i < totalLines; i++) {

    const x = (i * step).toFixed(2);

    let y1 = 12, y2 = 22, strokeColor = '#3B4653', strokeWidth = '1';



    // Mark Window boundaries in Red

    if (i >= windowLeftIdx && i <= windowRightIdx) {

      strokeColor = '#F85149';

      strokeWidth = '1.4';

    }



    // Major markers

    if (i === centerIdx) {

      y1 = 4; y2 = 26;

      strokeColor = '#58A6FF';

      strokeWidth = '2';

    } else if (i === windowLeftIdx || i === windowRightIdx) {

      y1 = 6; y2 = 26;

      strokeColor = '#FF5252';

      strokeWidth = '2.5';

    } else if (i % 10 === 9) {

      y1 = 10; y2 = 24;

      if (strokeColor !== '#F85149') strokeColor = '#6E7681';

      strokeWidth = '1.2';

    }



    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');

    line.setAttribute('x1', x);

    line.setAttribute('y1', y1);

    line.setAttribute('x2', x);

    line.setAttribute('y2', y2);

    line.setAttribute('stroke', strokeColor);

    line.setAttribute('stroke-width', strokeWidth);

    g.appendChild(line);

  }



  // Update ruler labels

  const half = Math.round(halfWindowMm);

  const markWinLabel = document.getElementById('lbl-mark-win');

  if (markWinLabel) markWinLabel.textContent = `${HMI_STATE.recipe.markWindow}mm (±${half}mm)`;

  const leftWinLabel = document.getElementById('legend-left-win');

  if (leftWinLabel) leftWinLabel.textContent = `-${half}mm`;

  const rightWinLabel = document.getElementById('legend-right-win');

  if (rightWinLabel) rightWinLabel.textContent = `+${half}mm`;



  // Draw current mark position indicator inside mark window

  updateMarkWindowWithError(window.lastReportedErrorMm);

}

