function updateRepAndRulerDisplay(repeatLengthActual, markError, markErrorValid, isOff) {

  const repEl = document.getElementById('mark-error-readout');

  const m1El = document.getElementById('m1-c1-value');

  const m2El = document.getElementById('m2-c2-value');

  const indGroup = document.getElementById('ruler-mark-indicator');

  const markTag = document.getElementById('ruler-live-mark-tag');



  const rec = (window.HMI_STATE && window.HMI_STATE.recipe) ? window.HMI_STATE.recipe : { markWindow: 40 };

  const markWin = Number(rec.markWindow) || 40;

  const halfWin = markWin / 2;



  const repAct = (typeof repeatLengthActual === 'number') ? repeatLengthActual : 0.0;

  const errMm = (typeof markError === 'number') ? markError : 0.0;

  const isValid = Boolean(markErrorValid) && Math.abs(errMm) < 100.0 && !isOff;



  // 1. REP display formatting per Section 4a:

  // - "REP: 740.0 mm +1.00 mm" or "REP: 740.0 mm -1.00 mm"

  // - When error not valid: "REP: 740.0 mm ± --"

  // - When length not measured (OFF mode or repAct == 0): "REP: --- mm"

  if (repEl) {

    if (isOff || repAct <= 0.0) {

      repEl.textContent = 'REP: --- mm';

      repEl.style.color = '#8b949e';

    } else if (!isValid) {

      repEl.textContent = `REP: ${repAct.toFixed(1)} mm ± --`;

      repEl.style.color = '#e3b341';

    } else {

      const signStr = errMm >= 0 ? '+' : '-';

      const absVal = Math.abs(errMm);

      repEl.textContent = `REP: ${repAct.toFixed(1)} mm ${signStr}${absVal.toFixed(2)} mm`;

      const pass = absVal <= 7.0;

      repEl.style.color = pass ? 'var(--green-bright)' : (absVal <= 15.0 ? 'var(--amber-bright)' : 'var(--red-bright)');

    }

  }



  // 2. M1 and M2 values (mm)

  if (m1El && m2El) {

    if (isOff || !isValid || repAct <= 0.0) {

      m1El.textContent = '0.0';

      m2El.textContent = '0.0';

    } else {

      const absVal = Math.abs(errMm);

      if (errMm < -0.005) {

        m1El.textContent = absVal.toFixed(1);

        m2El.textContent = '0.0';

      } else if (errMm > 0.005) {

        m1El.textContent = '0.0';

        m2El.textContent = absVal.toFixed(1);

      } else {

        m1El.textContent = '0.0';

        m2El.textContent = '0.0';

      }

    }

  }



  // 3. mm scale pointer: strictly uses the same markError and sign (HMI_CHANGES §4a)

  // Parked at center (0) and greyed if isOff or !isValid

  if (indGroup) {

    let posX = 175;

    let colorHex = '#64748b';

    if (!isOff && isValid && repAct > 0.0) {

      posX = Math.max(6, Math.min(344, 175 + (errMm * 3.5)));

      const absVal = Math.abs(errMm);

      colorHex = absVal <= 7.0 ? '#7ee787' : (absVal <= 15.0 ? '#e3b341' : '#ff7b72');

    }

    indGroup.innerHTML = `

      <line x1="${posX.toFixed(1)}" y1="2" x2="${posX.toFixed(1)}" y2="28" stroke="${colorHex}" stroke-width="2.5" stroke-linecap="round"/>

      <polygon points="${(posX-3.5).toFixed(1)},1 ${(posX+3.5).toFixed(1)},1 ${posX.toFixed(1)},6" fill="${colorHex}"/>

      <polygon points="${(posX-3.5).toFixed(1)},29 ${(posX+3.5).toFixed(1)},29 ${posX.toFixed(1)},24" fill="${colorHex}"/>

      <circle cx="${posX.toFixed(1)}" cy="15" r="3.2" fill="${colorHex}" stroke="#05080c" stroke-width="1.2"/>

    `;

  }



  // 4. Ruler header live tag

  if (markTag) {

    if (isOff) {

      markTag.textContent = 'ERR: 0.0mm (OFF)';

      markTag.style.color = '#64748b';

      markTag.style.background = '#090d14';

      markTag.style.borderColor = '#1e293b';

    } else if (!isValid || repAct <= 0.0) {

      markTag.textContent = 'ERR: ± -- (NO MARK)';

      markTag.style.color = '#d29922';

      markTag.style.background = '#2e2305';

      markTag.style.borderColor = '#d29922';

    } else {

      const absVal = Math.abs(errMm);

      const isInsideWindow = absVal <= halfWin;

      const isPass = absVal <= 7.0;

      const signStr = errMm >= 0 ? '+' : '-';

      markTag.textContent = `ERR: ${signStr}${absVal.toFixed(2)}mm (${isInsideWindow ? 'IN WINDOW' : 'OUT OF WINDOW'})`;

      markTag.style.color = isPass ? '#7ee787' : (isInsideWindow ? '#e3b341' : '#ff7b72');

      markTag.style.background = isInsideWindow ? (isPass ? '#0d2217' : '#2e2305') : '#2b1012';

      markTag.style.borderColor = isInsideWindow ? (isPass ? '#2ea043' : '#d29922') : '#f85149';

    }

  }

}

