function updateDynamicCounterBands(bands, counters, errorMm, isValid) {

  const gridEl = document.querySelector('#col-stn2 .detection-grid');

  const errRowEl = document.querySelector('#col-stn2 .mark-error-only');

  if (!gridEl) return;



  const safeBands = (Array.isArray(bands) && bands.length > 0) ? bands : [

    { key: '0-7', label: '0-7 mm' },

    { key: '8-15', label: '8-15 mm' },

    { key: '16-25', label: '16-25 mm' }

  ];

  const safeCounters = counters || {};

  const isStn2Off = (window.HMI_STATE?.stn2?.mode === 'OFF');

  const isErrValid = Boolean(isValid) && !isStn2Off && typeof errorMm === 'number';



  // Active band based on error rounded to whole mm (negative same as positive)

  let activeBandKey = '';

  if (isErrValid) {

    const roundedErr = Math.round(Math.abs(errorMm));

    if (roundedErr <= 7) {

      activeBandKey = '0-7';

    } else if (roundedErr <= 15) {

      activeBandKey = safeBands.some(b => b.key === '8-10') && roundedErr <= 10 ? '8-10' : '8-15';

    } else if (roundedErr <= 25) {

      activeBandKey = safeBands.some(b => b.key === '16-20') && roundedErr <= 20 ? '16-20' : '16-25';

    } else {

      activeBandKey = safeBands.some(b => b.key === '26-window') ? '26-window' : '26-plus';

    }

  }



  const N = safeBands.length + 1;



  const existingChips = gridEl.querySelectorAll('.zone-chip');

  let needRebuild = existingChips.length !== N;

  if (!needRebuild) {

    safeBands.forEach((band, i) => {

      if (existingChips[i].getAttribute('data-zone') !== band.key ||

          existingChips[i].querySelector('small')?.textContent !== band.label) {

        needRebuild = true;

      }

    });

  }



  if (needRebuild) {

    let html = '';

    safeBands.forEach(band => {

      const cnt = safeCounters[band.key] ?? 0;

      const isActive = (band.key === activeBandKey);

      html += `<div class="zone-chip${isActive ? ' active' : ''}" data-zone="${band.key}"><small>${band.label}</small><b id="zone-${band.key}-count">${cnt}</b></div>`;

    });

    const totalCnt = safeCounters.total ?? 0;

    html += `<div class="zone-chip" data-zone="man"><small>TOTAL</small><b id="zone-total-count">${totalCnt}</b></div>`;

    gridEl.innerHTML = html;

  } else {

    safeBands.forEach((band, i) => {

      const chip = existingChips[i];

      if (chip) {

        const cntEl = chip.querySelector('b');

        if (cntEl) cntEl.textContent = safeCounters[band.key] ?? 0;

        chip.classList.toggle('active', band.key === activeBandKey);

      }

    });

    const totalChip = existingChips[existingChips.length - 1];

    if (totalChip) {

      const totalB = totalChip.querySelector('b');

      if (totalB) totalB.textContent = safeCounters.total ?? 0;

    }

  }



  // Ensure perfect alignment: M1 in col 1, M2 in col N, REP in col 2 to N-1

  gridEl.style.setProperty('grid-template-columns', `repeat(${N}, minmax(0, 1fr))`, 'important');

  if (errRowEl) {

    errRowEl.style.setProperty('grid-template-columns', `repeat(${N}, minmax(0, 1fr))`, 'important');

    const m1 = document.getElementById('mark-error-m1');

    const rep = document.getElementById('mark-error-readout');

    const m2 = document.getElementById('mark-error-m2');

    if (m1) m1.style.setProperty('grid-column', '1', 'important');

    if (m2) m2.style.setProperty('grid-column', String(N), 'important');

    if (rep) rep.style.setProperty('grid-column', `2 / ${N}`, 'important');

  }

}

