async function pollFBarXState() {

  if (pollFBarXState._inFlight) return;

  pollFBarXState._inFlight = true;

  try {

    const res = await fetch('/api/fbarx/state');

    if (!res.ok) throw new Error('HTTP ' + res.status);

    const data = await res.json();

    if (!data) return;



    // 1. Connection status (honest): OK | NOT CONNECTED | WRONG FIRMWARE | SIMULATED

    window._fbarxStatus = data.status;

    window._fbarxPollOk = true;

    const live = (data.status === 'OK' || data.status === 'SIMULATED');

    const statusDots = document.querySelectorAll('.serial-port-dot, #status-bar .status-dot, .port-status-dot');

    statusDots.forEach(dot => {

      dot.classList.toggle('online', live);

      dot.classList.toggle('offline', !live);

      dot.style.background = data.status === 'OK' ? '#20e85a' : (data.status === 'SIMULATED' ? '#f5a623' : '#ff3b30');

    });

    setFbarxBanner(data.status);

    document.getElementById('col-stn2')?.classList.toggle('link-down', !live);

    if (!live) return;          // do not draw stale numbers as live values



    // 2. STN 2 Mode sync

    if (data.mode && !window._userModeSwitching) {

      if (HMI_STATE.stn2.mode !== data.mode) {

        HMI_STATE.stn2.mode = data.mode;

        document.querySelectorAll('#col-stn2 .mode-btn').forEach(btn => {

          btn.classList.toggle('active', btn.dataset.mode === data.mode);

        });

        if (typeof applyModeInteractionState === 'function') applyModeInteractionState();

        if (typeof refreshUI === 'function') refreshUI();

      }

    }



    // 3. STN 2 Output %

    if (typeof data.outputPct === 'number') {

      HMI_STATE.stn2.outputPct = data.outputPct;

      const bar = document.getElementById('stn2-out-bar');

      const txt = document.getElementById('stn2-out-bar-txt');

      if (bar) bar.style.width = Math.max(0, Math.min(100, data.outputPct)) + '%';

      if (txt) txt.textContent = (data.outputPct % 1 === 0 ? Math.round(data.outputPct) : data.outputPct.toFixed(1)) + '%';

    }



    // 4. Line Speed

    if (typeof data.speedMpm === 'number') {

      HMI_STATE.stn2.speedMpm = data.speedMpm;

      const speedEls = document.querySelectorAll('#stn2-line-speed, #status-speed-val, [data-stn2-speed]');

      speedEls.forEach(el => el.textContent = data.speedMpm);

    }



    // 5. STN 2 Ammeter (Brake current actual reg 82)

    if (typeof data.ammeter === 'number') {

      HMI_STATE.stn2.ammeter = data.ammeter;

      if (typeof window.renderLiveAmmeters === 'function') window.renderLiveAmmeters();

    }



    // 6. Recipe Repeat Length Set & Mark Window

    if (activeNumpadTarget !== 'repeat' && typeof data.repeatLength === 'number' && data.repeatLength >= 100) {

      if (HMI_STATE.recipe) HMI_STATE.recipe.repeatLength = data.repeatLength;

      const dispRepeat = document.getElementById('disp-repeat');

      if (dispRepeat) dispRepeat.textContent = data.repeatLength;

    }

    if (activeNumpadTarget !== 'markwin' && typeof data.markWindow === 'number' && data.markWindow >= 10) {

      if (HMI_STATE.recipe) {

        const oldMw = HMI_STATE.recipe.markWindow;

        HMI_STATE.recipe.markWindow = data.markWindow;

        if (oldMw !== data.markWindow && typeof initRuler99Ticks === 'function') {

          initRuler99Ticks();

        }

      }

      const dispWindow = document.getElementById('disp-window');

      if (dispWindow) dispWindow.textContent = data.markWindow;

    }



    // 7. Measured Repeat Length, M1, M2 & Ruler Scale needle (HMI_CHANGES §4a)

    updateRepAndRulerDisplay(data.repeatLengthActual, data.markError, data.markErrorValid, data.mode === 'OFF');



    // 8. Dynamic Bag Counters & Error Bands (HMI_CHANGES §4b)

    updateDynamicCounterBands(data.counterBands, data.counters, data.markError, data.markErrorValid);



    // The link (board) is the only counter. Job-end report reads this.

    if (data.counters) { HMI_STATE.report = HMI_STATE.report || {}; HMI_STATE.report.counters = Object.assign({}, data.counters); }



  } catch(e) {

    window._fbarxStatus = 'NOT CONNECTED';

    setFbarxBanner('NOT CONNECTED');

    document.getElementById('col-stn2')?.classList.add('link-down');

    document.querySelectorAll('.serial-port-dot, #status-bar .status-dot, .port-status-dot')

      .forEach(dot => { dot.style.background = '#ff3b30'; });

  } finally {

    pollFBarXState._inFlight = false;

  }

}

