        btn.classList.add('active');

        const mode = btn.dataset.mode;

        HMI_STATE[station].mode = mode;

        if (station === 'stn2') {

          fbarxPost('/api/fbarx/mode', { mode }).then(r => { if (!r.ok) showToast(r.error || 'BOARD DID NOT ACCEPT MODE'); });

        }

        // Never leave an editable keypad open after its station leaves MAN mode.

        const keypadTargetsByStation = station === 'stn1'

          ? ['stension', 'stn1output']

          : ['repeat', 'markwin', 'stn2output'];

        if (mode !== 'MAN' && keypadTargetsByStation.includes(activeNumpadTarget)) {

          document.getElementById('numpad-modal')?.classList.remove('open');

          activeNumpadTarget = '';

        }



        if (mode === 'OFF') {

          HMI_STATE[station].outputPct = 0.0;

        } else if (mode === 'AUTO') {

          HMI_STATE[station].outputPct = (station === 'stn1') ? 72.0 : 55.0;

        }



        // Apply mode class

        if (colCard) {

          colCard.classList.remove('mode-auto', 'mode-man', 'mode-off');

          if (mode === 'AUTO') colCard.classList.add('mode-auto');

          else if (mode === 'MAN') colCard.classList.add('mode-man');

          else if (mode === 'OFF') colCard.classList.add('mode-off');

        }



        refreshUI();

        applyModeInteractionState();

        if (typeof updateCameraForStationModes === 'function') updateCameraForStationModes();

      });

    });

  });

}

