function updateCameraForStationModes() {

  const stnState = (typeof HMI_STATE !== 'undefined' ? HMI_STATE : (window.HMI_STATE || {}));

  const s2Mode = stnState?.stn2?.mode || 'OFF';



  const led = document.getElementById('live-cam-led');

  const stat = document.getElementById('live-cam-top-stat');

  const titleLbl = document.getElementById('live-cam-title-lbl');

  const liveCamImg = document.getElementById('recipe-live-cam-img');

  const offOverlay = document.getElementById('live-cam-off-overlay');

  const livePlate = document.getElementById('recipe-live-cam-plate');



  const isStn2Man = (s2Mode === 'MAN');

  const isStn2Auto = (s2Mode === 'AUTO');

  const isStn2Off = (s2Mode === 'OFF');



  // Always keep livePlate clickable so the operator can open the camera inspection screen at any time

  if (livePlate) {

    livePlate.style.cursor = 'pointer';

    livePlate.title = isStn2Auto ? 'Open Live Camera Inspection (AUTO)' : (isStn2Man ? 'Open Live Inspection Criteria (MAN)' : 'Open Camera Inspection (STANDBY)');

  }



  // Also sync the full camera mode badge if the camera screen is open

  const modeBadge = document.getElementById('full-cam-mode-badge');

  if (modeBadge) {

    if (isStn2Auto) {

      modeBadge.textContent = 'AUTO LIVE';

      modeBadge.style.color = '#7ee787';

      modeBadge.style.borderColor = '#2ea043';

      modeBadge.style.background = '#0d2217';

    } else if (isStn2Man) {

      modeBadge.textContent = 'MAN LIVE';

      modeBadge.style.color = '#38bdf8';

      modeBadge.style.borderColor = '#38bdf8';

      modeBadge.style.background = '#081d33';

    } else {

      modeBadge.textContent = 'STANDBY LIVE';

      modeBadge.style.color = '#f59e0b';

      modeBadge.style.borderColor = '#d97706';

      modeBadge.style.background = '#261c02';

    }

  }



  // If user has not activated the camera (e.g. fresh reload or station is OFF):

  if (!window.isCameraUserActive || isStn2Off) {

    if (offOverlay) offOverlay.style.display = 'flex';

    if (liveCamImg) liveCamImg.style.display = 'none';

    if (led) {

      led.classList.remove('active');

      led.style.background = isStn2Auto ? '#2ea043' : (isStn2Man ? '#388bfd' : '#475569');

      led.style.boxShadow = 'none';

    }

    if (titleLbl) titleLbl.style.color = isStn2Auto ? '#7ee787' : (isStn2Man ? '#79c0ff' : '#64748b');

    if (stat) {

      stat.textContent = 'CAMERA OFF';

      stat.style.color = '#8b949e';

      stat.style.borderColor = '#30363d';

      stat.style.background = '#161b22';

    }

    if (isStn2Off && liveDisplacementTimer) {

      clearInterval(liveDisplacementTimer);

      liveDisplacementTimer = null;

    }

    return;

  }



  // User HAS explicitly activated the camera and Station 2 is in AUTO or MAN:

  if (offOverlay) offOverlay.style.display = 'none';

  if (liveCamImg) {

    liveCamImg.style.display = 'block';

    liveCamImg.style.opacity = '1.0';

    liveCamImg.style.filter = 'none';

  }

  if (led) {

    led.classList.add('active');

    led.style.background = isStn2Auto ? '#10b981' : '#38bdf8';

    led.style.boxShadow = isStn2Auto ? '0 0 8px #10b981' : '0 0 8px #38bdf8';

  }

  if (titleLbl) titleLbl.style.color = isStn2Auto ? '#10b981' : '#38bdf8';

  if (stat) {

    stat.textContent = isStn2Auto ? 'LIVE CAM' : 'LIVE FEED';

    stat.style.color = isStn2Auto ? '#10b981' : '#38bdf8';

    stat.style.borderColor = isStn2Auto ? '#10b981' : '#38bdf8';

    stat.style.background = isStn2Auto ? '#062316' : '#081d33';

  }

  if (typeof startLiveCamera === 'function') {

    startLiveCamera();

  } else if (typeof startLiveCameraFeed === 'function') {

    startLiveCameraFeed(true);

  }

  if (typeof calculateFrontBackDistance === 'function') {

    calculateFrontBackDistance(stnState.recipe);

  }

  if (!liveDisplacementTimer) {

    liveDisplacementTimer = setInterval(() => {

      const curMode = (window.HMI_STATE?.stn2?.mode || 'OFF');

      if (window.isCameraUserActive && (curMode === 'AUTO' || curMode === 'MAN')) {

        if (typeof calculateFrontBackDistance === 'function') {

          calculateFrontBackDistance(window.HMI_STATE?.recipe);

        }

      } else {

        clearInterval(liveDisplacementTimer);

        liveDisplacementTimer = null;

      }

    }, 2500);

  }

}

