function applyModeInteractionState() {

  const setEnabled = (el, enabled) => {

    if (!el) return;

    el.style.pointerEvents = enabled ? '' : 'none';

    el.setAttribute('aria-disabled', enabled ? 'false' : 'true');

    if ('disabled' in el && el.tagName === 'BUTTON') el.disabled = !enabled;

  };

  const setGroup = (selector, enabled, root=document) => root.querySelectorAll(selector).forEach(el => setEnabled(el, enabled));



  const s1 = HMI_STATE.stn1.mode;

  const s2 = HMI_STATE.stn2.mode;

  const s1col = document.getElementById('col-stn1');

  const s2col = document.getElementById('col-stn2');



  // STN1: output and ammeter in AUTO/MAN; tension cards stay visible in all modes.

  setEnabled(document.getElementById('stn1-out-row'), s1 === 'AUTO' || s1 === 'MAN');

  setEnabled(document.getElementById('stn1-ammeter-card'), s1 === 'AUTO' || s1 === 'MAN');

  // Keep S-Tension parent div full opacity & readable; numpad click is guarded in openStensionPad

  const s1a = document.getElementById('stn1-atension-val')?.closest('.tension-card');

  setEnabled(s1a, s1 === 'AUTO');

  setEnabled(document.getElementById('stn1-unit-toggle'), s1 === 'AUTO' || s1 === 'MAN');

  setGroup('#stn1-step-down, #stn1-step-up', s1 === 'MAN');

  setEnabled(document.getElementById('btn-stn1-cal'), true);



  // Grey out ONLY STN1 numpad symbols in AUTO or OFF state

  const s1StensionBox = document.getElementById('stn1-stension-box');

  if (s1StensionBox) {

    s1StensionBox.title = s1 === 'MAN' ? 'Click to input target S-Tension value via numpad' : 'S-Tension target value (numpad disabled in ' + s1 + ' mode)';

    s1StensionBox.style.cursor = s1 === 'MAN' ? 'pointer' : 'default';

    const sym = s1StensionBox.querySelector('.editable-numpad-symbol');

    if (sym) {

      sym.classList.toggle('numpad-faded-off', s1 !== 'MAN');

      sym.classList.toggle('numpad-active-man', s1 === 'MAN');

    }

  }

  const s1OutPad = document.querySelector('#stn1-out-row [data-output-pad="stn1"]');

  if (s1OutPad) {

    s1OutPad.classList.toggle('numpad-faded-off', s1 !== 'MAN');

    s1OutPad.classList.toggle('numpad-active-man', s1 === 'MAN');

  }



  // STN2: output/ammeter in AUTO/MAN; mark position and range zones in AUTO;

  // MAN zone and SCAN in AUTO/MAN; CAL remains available in every mode.

  setEnabled(document.getElementById('stn2-out-row'), s2 === 'AUTO' || s2 === 'MAN');

  setEnabled(document.getElementById('stn2-ammeter-card'), s2 === 'AUTO' || s2 === 'MAN');

  setGroup('.mark-position-card, .mark-position-wrap, .mark-position-panel, .mark-position-ruler', s2 === 'AUTO', s2col || document);

  setGroup('.detection-grid .zone-chip[data-zone="0-7"], .detection-grid .zone-chip[data-zone="16-25"]', s2 === 'AUTO', s2col || document);

  setGroup('.detection-grid .zone-chip[data-zone="man"]', s2 === 'AUTO' || s2 === 'MAN', s2col || document);

  setEnabled(document.querySelector('#col-stn2 .detection-grid .zone-chip[data-zone="8-15"]'), s2 === 'AUTO');

  setEnabled(document.getElementById('btn-scan-trigger'), s2 === 'AUTO' || s2 === 'MAN');

  setEnabled(document.getElementById('btn-stn2-cal'), true);



  // Grey out ONLY STN2 output numpad symbol in AUTO or OFF state

  const s2OutPad = document.querySelector('#stn2-out-row [data-output-pad="stn2"]');

  if (s2OutPad) {

    s2OutPad.classList.toggle('numpad-faded-off', s2 !== 'MAN');

    s2OutPad.classList.toggle('numpad-active-man', s2 === 'MAN');

  }



  // M1/M2 readout fields remain available in OFF; do not disable their wrappers.

  setEnabled(document.getElementById('mark-error-m1'), true);

  setEnabled(document.getElementById('mark-error-m2'), true);



  // Shared recipe parameters: parent divs STAY 100% visible and readable; grey out ONLY the numpad symbol

  const recipeEditable = s2 === 'MAN';

  const tileRepeat = document.getElementById('tile-repeat-length');

  if (tileRepeat) {

    tileRepeat.title = recipeEditable ? 'Click to edit Repeat Length via numpad' : 'Repeat Length (numpad disabled in ' + s2 + ' mode)';

    tileRepeat.style.cursor = recipeEditable ? 'pointer' : 'default';

    tileRepeat.classList.toggle('interactive', recipeEditable);

    const sym = tileRepeat.querySelector('.editable-numpad-symbol');

    if (sym) {

      sym.classList.toggle('numpad-faded-off', !recipeEditable);

      sym.classList.toggle('numpad-active-man', recipeEditable);

    }

  }

  const tileWindow = document.getElementById('tile-mark-window');

  if (tileWindow) {

    tileWindow.title = recipeEditable ? 'Click to edit Mark Window via numpad' : 'Mark Window (numpad disabled in ' + s2 + ' mode)';

    tileWindow.style.cursor = recipeEditable ? 'pointer' : 'default';

    tileWindow.classList.toggle('interactive', recipeEditable);

    const sym = tileWindow.querySelector('.editable-numpad-symbol');

    if (sym) {

      sym.classList.toggle('numpad-faded-off', !recipeEditable);

      sym.classList.toggle('numpad-active-man', recipeEditable);

    }

  }



  // Mode-dependent inactive underline treatment uses existing station mode classes only.

  [s1col, s2col].forEach((col, idx) => {

    if (!col) return;

    const mode = idx === 0 ? s1 : s2;

    const title = col.querySelector('.col-header .col-title > span:first-child');

    if (title) title.classList.toggle('mode-interaction-inactive', mode === 'OFF');

  });

}

