code_full:
function bindStn1Calibration() {

  const screen=document.getElementById('stn1-cal-screen');

  const open=()=>{

    screen.classList.add('open');

    document.getElementById('stn1-password-screen').style.display='flex';

    document.getElementById('stn1-control-screen').style.display='none';

    document.getElementById('stn1-loadcell-screen').style.display='none';

    document.getElementById('stn1-cal-badge').textContent='PASSWORD REQUIRED';

    // Open the password keypad immediately when CALIBRATE is pressed.

    setTimeout(()=>openCalibrationPad('password'),40);

  };

  const home=()=>{ screen.classList.remove('open'); document.getElementById('numpad-modal').classList.remove('open'); };

  const addAction = (id, fn) => {

    const el = document.getElementById(id);

    if (!el) return;

    el.addEventListener('click', fn);

    el.addEventListener('pointerup', fn);

  };

  addAction('btn-stn1-cal', open);

  addAction('stn1-cal-cancel', home);

  addAction('stn1-control-home', () => { discardStn1ControlDraft(); home(); });

  addAction('stn1-loadcell-home', () => { discardStn1LoadcellDraft(); home(); });

  addAction('stn1-loadcell-save', () => {

    // CONFIRM & SAVE commits the loadcell calibration values and returns HOME.

    if (!stn1LoadcellDraft) initStn1LoadcellDraft();

    const c=HMI_STATE.stn1.calibration;

    c.loadcellCapacity=Number(stn1LoadcellDraft.loadcellCapacity);

    c.knownWeight=Number(stn1LoadcellDraft.knownWeight);

    const applied=getStn1LoadcellValues();

    try { localStorage.setItem('stn1LoadcellCalibration', JSON.stringify(applied)); } catch(e) {}

    updateCalibrationDisplay();

    discardStn1LoadcellDraft();

    home();

  });

