function handleStn2CalibrationConfirm(){

  if(activeNumpadTarget==='stn2cal_password'){

    fbarxPost('/api/fbarx/unlock', { code: String(numpadBuffer||'') }).then(async r => {

      const modal = document.getElementById('numpad-modal');

      if(!r.ok){

        document.getElementById('numpad-display-val').textContent = 'INVALID'; isFirstNumpadKeypress = true;

        setTimeout(() => openProtectedNumericPassword('stn2cal_password','STN 2 PASSWORD'), 700); return;

      }

      window._calToken = r.token;

      modal.classList.remove('open'); modal.querySelector('.numpad-modal').classList.remove('password-entry');

      document.getElementById('numpad-btn-ok').textContent = 'CONFIRM & SET';

      try {

        const g = await fetch('/api/fbarx/calibration');

        if (g.ok) HMI_STATE.stn2.calibration = { ...HMI_STATE.stn2.calibration, ...(await g.json()) };

        else showToast('NOT CONNECTED: showing last known values');

      } catch(e) { showToast('NOT CONNECTED: showing last known values'); }

      initStn2CalDraft(); updateStn2CalDisplay();

      document.getElementById('stn2-cal-screen').classList.add('open');

    });

    return;

  }

  const target=activeNumpadTarget.replace('stn2cal_',''); const v=Number(numpadBuffer);

  const ranges={

    acErr:[0.1,99.9],

    dcErr:[0,999],

    spkErr:[0,999],

    encoderPprSet:[100,9999],

    markOffset:[-999,999],

    cylinderCircumference:[50,9999],

    b2bAlarm:[5,25],

    markSkipAlarm:[1,9],

    brakePower:[0,100],

    brakeCapacity:[1,20],

    brakeCurrent:[0.0,5.0],

    brakeCurrentCal:[1000,30000]

  };

  if(!Number.isFinite(v) || !ranges[target] || v<ranges[target][0] || v>ranges[target][1]){

    document.getElementById('numpad-display-val').textContent='INVALID';

    isFirstNumpadKeypress = true;

    return false;

  }

  if(!stn2CalDraft) initStn2CalDraft();

  stn2CalDraft[target]=(target==='acErr'||target==='brakeCurrent')?Math.round(v*10)/10:Math.round(v);

  updateStn2CalDisplay();

  document.getElementById('numpad-modal').classList.remove('open');

  document.getElementById('numpad-modal').querySelector('.numpad-modal').classList.remove('password-entry');

  return true;

}

