function bindNumpad() {

  const box = document.getElementById('stn1-stension-box');

  const modal = document.getElementById('numpad-modal');

  const display = document.getElementById('numpad-display-val');

  const cancelBtn = document.getElementById('numpad-btn-cancel');

  const okBtn = document.getElementById('numpad-btn-ok');



  const openStensionPad = () => {

    if (HMI_STATE.stn1.mode !== 'MAN') return;

    activeNumpadTarget = 'stension';

    const isN = HMI_STATE.stn1.unit === 'N';

    const currentVal = isN ? String(Math.round(HMI_STATE.stn1.sTension * 9.80665)) : HMI_STATE.stn1.sTension.toFixed(1);

    numpadBuffer = currentVal;

    isFirstNumpadKeypress = true;



    document.getElementById('numpad-target-title').textContent = 'ENTER S-TENSION VALUE (0 - 99.9)';

    document.getElementById('numpad-unit-hint').textContent = HMI_STATE.stn1.unit;

    document.getElementById('numpad-prev-label').textContent = 'CURRENT SET VALUE:';

    document.getElementById('numpad-prev-val').textContent = `${currentVal} ${HMI_STATE.stn1.unit}`;

    display.textContent = currentVal;

    modal.classList.add('open');

  };

  box.addEventListener('click', openStensionPad);

  box.addEventListener('pointerup', (e) => { if (e.pointerType === 'touch') openStensionPad(); });



  document.querySelectorAll('.num-key').forEach(k => {

    k.addEventListener('click', () => {

      const val = k.dataset.k;

      const isPassword = (activeNumpadTarget === 'recipecal_password' || activeNumpadTarget.endsWith('_password') || activeNumpadTarget.startsWith('cal_password') || activeNumpadTarget.startsWith('stn2cal_password'));



      if (val === 'C' || val === 'CLR' || val === 'CLEAR') {

        numpadBuffer = '';

        isFirstNumpadKeypress = false;

      } else if (val === 'BACKSPACE' || val === 'DEL' || val === 'DELETE') {

        if (isPassword) {

          numpadBuffer = (numpadBuffer && numpadBuffer.length > 0) ? numpadBuffer.slice(0, -1) : '';

          isFirstNumpadKeypress = false;

        } else {

          if (isFirstNumpadKeypress) {

            numpadBuffer = (numpadBuffer && numpadBuffer.length > 1) ? numpadBuffer.slice(0, -1) : '';

            isFirstNumpadKeypress = false;

          } else {

            numpadBuffer = (numpadBuffer && numpadBuffer.length > 0) ? numpadBuffer.slice(0, -1) : '';

          }

          if (numpadBuffer === '' || numpadBuffer === '-') numpadBuffer = '';

        }

      } else if (val === '.') {

        if (isPassword) return;

        if (isFirstNumpadKeypress || !numpadBuffer) {

          numpadBuffer = '0.';

          isFirstNumpadKeypress = false;

        } else if (!numpadBuffer.includes('.')) {

          numpadBuffer += '.';

        }

      } else if (val === 'SIGN') {

        if (['recipecal_markOffset','stn2cal_markOffset'].includes(activeNumpadTarget)) {

          const n = parseFloat(numpadBuffer || '0');

          if (Number.isFinite(n)) {

            const magnitude = String(Math.abs(n));

            numpadBuffer = (n < 0 ? '' : '-') + magnitude;

            isFirstNumpadKeypress = false;

          }

        }

      } else {

        // Digits 0-9

        if (isFirstNumpadKeypress) {

          numpadBuffer = val;

          isFirstNumpadKeypress = false;

        } else {

          if (isPassword) {

            if (numpadBuffer.length < 8) numpadBuffer += val;

          } else {

            if (numpadBuffer === '0' || numpadBuffer === '') numpadBuffer = val;

            else if (numpadBuffer.length < 5) numpadBuffer += val;

          }

        }

      }



      if (isPassword) {

        display.textContent = numpadBuffer;

      } else {

        display.textContent = numpadBuffer === '' ? '0' : numpadBuffer;

      }

    });

  });



  cancelBtn.addEventListener('click', () => {

    modal.classList.remove('open');

    modal.querySelector('.numpad-modal').classList.remove('password-entry');

    okBtn.textContent='CONFIRM & SET';

    if (activeNumpadTarget === 'cal_password') { document.getElementById('stn1-cal-screen')?.classList.remove('open'); }

    if (activeNumpadTarget === 'stn2cal_password') { document.getElementById('stn2-cal-screen')?.classList.remove('open'); }

    activeNumpadTarget='';

  });



  // Physical Keyboard Support for Numpad Modal

  window.addEventListener('keydown', (e) => {

    const numModal = document.getElementById('numpad-modal');

    if (!numModal || !numModal.classList.contains('open')) return;



    if (e.key === 'Escape') {

      e.preventDefault();

      cancelBtn.click();

      return;

    }

    if (e.key === 'Enter') {

      e.preventDefault();

      okBtn.click();

      return;

    }



    let targetKey = null;

    if (e.key >= '0' && e.key <= '9') {

      targetKey = e.key;

    } else if (e.key === '.' || e.key === ',') {

      targetKey = '.';

    } else if (e.key === '-' || e.key === '+' || e.key === '±') {

      targetKey = 'SIGN';

    } else if (e.key === 'Backspace') {

      targetKey = 'BACKSPACE';

    } else if (e.key === 'Delete' || e.key.toLowerCase() === 'c') {

      targetKey = 'C';

    }



    if (targetKey) {

      e.preventDefault();

      const btn = numModal.querySelector(`.num-key[data-k="${targetKey}"]`);

      if (btn && btn.style.visibility !== 'hidden' && getComputedStyle(btn).visibility !== 'hidden') {

        btn.classList.add('active-press');

        setTimeout(() => btn.classList.remove('active-press'), 120);

        btn.click();

      }

    }

  });



  okBtn.addEventListener('click', async () => {

    if (activeNumpadTarget.startsWith('cal_')) { handleCalibrationConfirm(); return; }

    if (activeNumpadTarget.startsWith('stn2cal_')) { handleStn2CalibrationConfirm(); return; }

    if (activeNumpadTarget==='recipecal_password') { handleProtectedPasswordConfirm('recipecal_password','4444',()=>{ if(typeof window.openRecipeCalibrationForm==='function') window.openRecipeCalibrationForm(); else { document.getElementById('recipe-calibration-overlay')?.classList.add('open'); syncRecipe(); } },'RECIPE CALIBRATION PASSWORD'); return; }

    if (activeNumpadTarget.startsWith('recipecal_')) { handleRecipeNumericConfirm(); return; }

    let parsed = parseFloat(numpadBuffer) || 0;



    if (activeNumpadTarget === 'stension') {

      const isN = HMI_STATE.stn1.unit === 'N';

      if (isN) {

        parsed = parsed / 9.80665;

      }

      parsed = Math.max(0.0, Math.min(99.9, parsed));

      HMI_STATE.stn1.sTension = parsed;

      fbarxPost('/api/fbarx/tension', { kg: parsed }).then(r => { if (!r.ok) showToast('SET TENSION NOT SENT TO STN 2: ' + (r.error || '')); });

      if (HMI_STATE.recipe) {

        HMI_STATE.recipe.sTensionTarget = parsed;

        if (HMI_STATE.recipe.id && window.RecipeDB) {

          const cur = RecipeDB.get(HMI_STATE.recipe.id);

          if (cur) { cur.sTensionTarget = parsed; RecipeDB.save(cur).catch(()=>{}); }

        }

      }

    } else if (activeNumpadTarget === 'stn1output') {

      HMI_STATE.stn1.outputPct = normalizeOutput(parsed);

    } else if (activeNumpadTarget === 'stn2output') {

      HMI_STATE.stn2.outputPct = normalizeOutput(parsed);

      fbarxPost('/api/fbarx/output', { pct: HMI_STATE.stn2.outputPct }).then(r => { if (!r.ok) showToast(r.error || 'OUTPUT NOT SENT TO BOARD'); });

    } else if (activeNumpadTarget === 'repeat') {

      parsed = Math.round(parsed);

      const r = await fbarxPost('/api/fbarx/repeat_length', { repeatLength: parsed });

      if (!r.ok) { showToast((r.error || 'BOARD DID NOT ACCEPT REPEAT LENGTH SET')); }   // old value stays

      else {

        HMI_STATE.recipe.repeatLength = parsed;

        if (HMI_STATE.recipe.id && window.RecipeDB) {

          const cur = RecipeDB.get(HMI_STATE.recipe.id);

          if (cur) { cur.repeatLength = parsed; RecipeDB.save(cur).catch(()=>{}); }

        }

      }

    } else if (activeNumpadTarget === 'markwin') {

      parsed = Math.round(parsed);

      const r = await fbarxPost('/api/fbarx/mark_window', { markWindow: parsed });

      if (!r.ok) { showToast((r.error || 'BOARD DID NOT ACCEPT MARK WINDOW')); }

      else {

        HMI_STATE.recipe.markWindow = parsed;

        if (HMI_STATE.recipe.id && window.RecipeDB) {

          const cur = RecipeDB.get(HMI_STATE.recipe.id);

          if (cur) { cur.markWindow = parsed; RecipeDB.save(cur).catch(()=>{}); }

        }

        initRuler99Ticks();

      }

    }



    modal.classList.remove('open');

    refreshUI();

  });

}

