function refreshUI() {

  // Close editable field numpads immediately whenever their station is not in MAN mode.

  const padTargetsByMode = { stension: HMI_STATE.stn1.mode, stn1output: HMI_STATE.stn1.mode, stn2output: HMI_STATE.stn2.mode, repeat: HMI_STATE.stn2.mode, markwin: HMI_STATE.stn2.mode };

  if (activeNumpadTarget && Object.prototype.hasOwnProperty.call(padTargetsByMode, activeNumpadTarget) && padTargetsByMode[activeNumpadTarget] !== 'MAN') {

    document.getElementById('numpad-modal')?.classList.remove('open');

    activeNumpadTarget = '';

  }

  const colStn1 = document.getElementById('col-stn1');

  const colStn2 = document.getElementById('col-stn2');



  // Sync mode classes for dynamic border glows

  const syncModeClass = (card, mode) => {

    if (!card) return;

    card.classList.remove('mode-auto', 'mode-man', 'mode-off');

    if (mode === 'AUTO') card.classList.add('mode-auto');

    else if (mode === 'MAN') card.classList.add('mode-man');

    else if (mode === 'OFF') card.classList.add('mode-off');

  };



  syncModeClass(colStn1, HMI_STATE.stn1.mode);

  syncModeClass(colStn2, HMI_STATE.stn2.mode);



  // Make each station title underline follow its selected AUTO / MAN / OFF button.

  const syncModeUnderline = (card, mode) => {

    if (!card) return;

    const header = card.querySelector(':scope > .col-header');

    if (!header) return;

    const colors = {

      AUTO: { border: '#20e85a', glow: 'rgba(32,232,90,.42)' },

      MAN:  { border: '#E3B341', glow: 'rgba(227,179,65,.38)' },

      OFF:  { border: '#ff3b30', glow: 'rgba(255,59,48,.38)' }

    };

    const selected = colors[mode] || colors.OFF;

    header.style.borderBottom = `2px solid ${selected.border}`;

    header.style.boxShadow = `0 2px 7px ${selected.glow}`;

  };

  syncModeUnderline(colStn1, HMI_STATE.stn1.mode);

  syncModeUnderline(colStn2, HMI_STATE.stn2.mode);



  // Machine state symbols: use a running figure in AUTO/MAN and a prohibited-person symbol in OFF.

  const stateIcons = {

    running: `<svg viewBox="0 0 32 32" width="15" height="15" role="img" aria-label="Running"><defs><linearGradient id="runnerStateGradient" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stop-color="#ffb020"/><stop offset=".48" stop-color="#ff3b5c"/><stop offset="1" stop-color="#8b35d8"/></linearGradient></defs><circle cx="23" cy="5" r="3.4" fill="url(#runnerStateGradient)"/><path d="M17 9l-5 6 5 3 3 5-4 5M15 13l6 2 4 5 4 0M13 15l-5 5M17 18l-7 8" fill="none" stroke="url(#runnerStateGradient)" stroke-width="4.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,

    idle: `<svg viewBox="0 0 32 32" width="15" height="15" role="img" aria-label="Idle"><circle cx="16" cy="16" r="13" fill="none" stroke="#f85149" stroke-width="3.2"/><circle cx="16" cy="10" r="2.6" fill="#f85149"/><path d="M16 14v7m0-4-4 3m4-3 4 3m-4 1-3 5m3-5 3 5M6.5 6.5l19 19" fill="none" stroke="#f85149" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`

  };

  [['stn1-machine-state', HMI_STATE.stn1.mode], ['stn2-machine-state', HMI_STATE.stn2.mode]].forEach(([id, mode]) => {

    const indicator = document.getElementById(id);

    if (!indicator) return;

    const running = mode !== 'OFF';

    indicator.classList.toggle('running', running);

    indicator.classList.toggle('idle', !running);

    indicator.setAttribute('aria-label', `Station ${id.startsWith('stn1') ? '1' : '2'} ${running ? 'running' : 'idle'}`);

    const icon = indicator.querySelector('.machine-state-icon');

    const label = indicator.querySelector('.state-label');

    if (icon) icon.innerHTML = running ? stateIcons.running : stateIcons.idle;

    if (label) label.textContent = running ? 'RUN' : 'IDLE';

  });



  // STN 1 Updates



  document.getElementById('stn1-out-bar').style.width = HMI_STATE.stn1.outputPct + '%';

  document.getElementById('stn1-out-bar-txt').textContent = formatOutput(HMI_STATE.stn1.outputPct) + '%';

