function updateDistanceDisplay(distanceMm, data) {

  const isStn2Off = (window.HMI_STATE?.stn2?.mode === 'OFF');

  if (isStn2Off) distanceMm = 0.0;



  const errValEl = document.getElementById('live-cam-err-val');

  const absErr = Math.abs(distanceMm);

  const isPass = (absErr <= 7.0) || ((data && data.status) === 'IN SPEC');

  const sign = distanceMm > 0 ? '+' : (distanceMm < 0 ? '' : '');

  const text = absErr < 0.05 ? '0.0 mm' : `${sign}${distanceMm.toFixed(1)} mm`;

  const color = (absErr <= 7.0) ? '#10b981' : (absErr <= 15.0 ? '#f59e0b' : '#f85149');

  if (errValEl) {

    errValEl.textContent = text;

    errValEl.style.color = isStn2Off ? '#64748b' : color;

  }

  // Note: STN 2 ruler & mark indicator are driven exclusively by FBARX link (updateRepAndRulerDisplay)

  const hudPill = document.getElementById('hud-error-pill');

  if (hudPill) {

    hudPill.textContent = `ALIGNMENT: 0.0mm • DISTANCE: ${text}`;

    hudPill.style.color = color;

    hudPill.style.borderColor = color;

  }

  const fullStat = document.getElementById('full-cam-reg-stat');

  if (fullStat) {

    fullStat.textContent = `DISTANCE (F-B): ${text} (${(data && data.status) || (isPass ? 'IN SPEC' : 'OUT OF SPEC')})`;

    fullStat.style.color = color;

  }

  const fpsStat = document.getElementById('full-cam-fps-stat');

  if (fpsStat && data && data.scale_px_per_mm) {

    fpsStat.textContent = `SCALE: ${data.scale_px_per_mm.toFixed(1)} px/mm • DIST: ${data.distance_px ? data.distance_px.toFixed(1) + 'px' : '—'} • ${(data.method || 'line').toUpperCase()}`;

  }

  const confVal = document.getElementById('cam-conf-val');

  if (confVal && data && typeof data.confidence === 'number') {

    confVal.textContent = data.confidence.toFixed(2);

  }

  const lblF = document.getElementById('hud-label-front');

  const lblB = document.getElementById('hud-label-back');

  if (lblF && data && typeof data.front_pct === 'number') {

    lblF.textContent = `FRONT: ${data.front_pct.toFixed(1)}%`;

  }

  if (lblB && data && typeof data.back_pct === 'number') {

    lblB.textContent = `BACK: ${data.back_pct.toFixed(1)}%`;

  }

  const lineF = document.getElementById('hud-line-front');

  const lineB = document.getElementById('hud-line-back');

  if (lineF && lineB) {

    const show = Boolean(data && typeof data.front_line_px === 'number');

    lineF.style.display = show ? 'block' : 'none';

    lineB.style.display = show ? 'block' : 'none';

  }

}

