  let t = document.getElementById('p1-toast');

  if(!t){

    t = document.createElement('div');

    t.id = 'p1-toast';

    document.body.appendChild(t);

  }

  t.textContent = msg;

  t.className = bad ? 'bad' : '';

  t.style.display = 'block';

  t.style.opacity = '1';

  clearTimeout(toastTimer);

  toastTimer = setTimeout(() => {

    t.style.opacity = '0';

    setTimeout(() => { t.style.display = 'none'; }, 200);

  }, bad ? 4500 : 3000);

}

