function formatTime(d){

  if(!d) return '';

  const date = (d instanceof Date) ? d : new Date(d);

  if(isNaN(date.getTime())) return '';

  const pad = n => String(n).padStart(2, '0');

  return `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;

}

