function updateJobUI(){

  const stopBtn = document.getElementById('btn-job-stop');

  const statusBadge = document.getElementById('recipe-job-status');

  const statusText = document.getElementById('recipe-job-status-text');

  const startTimeEl = document.getElementById('recipe-job-start-time');



  const endBarBtn = document.getElementById('btn-job-end-bar');

  if(jobState.active){

    if(stopBtn) {

      stopBtn.classList.add('running');

      stopBtn.style.display = 'inline-flex';

    }

    if(endBarBtn) {

      endBarBtn.style.display = 'inline-flex';

    }

    if(statusBadge) {

      statusBadge.className = 'recipe-loaded running';

      statusBadge.style.display = 'inline-flex';

    }

    if(statusText) statusText.textContent = 'RUNNING';

    if(startTimeEl) startTimeEl.textContent = formatTime(jobState.startTime);



    if(HMI_STATE.report && jobState.startTime){

      HMI_STATE.report.startDateTime = jobState.startTime.toISOString().slice(0, 16);

      const repStart = document.getElementById('report-disp-start');

      if(repStart) repStart.textContent = formatDateTime(jobState.startTime);

      const repInp = document.getElementById('report-start');

      if(repInp && !repInp.value) repInp.value = jobState.startTime.toISOString().slice(0, 16);

    }

  } else {

    if(stopBtn) {

      stopBtn.classList.remove('running');

      stopBtn.style.display = 'none';

    }

    if(endBarBtn) {

      endBarBtn.style.display = 'none';

    }

    if(jobState.endTime && jobState.durationStr){

      if(statusBadge) {

        statusBadge.className = 'recipe-loaded stopped';

        statusBadge.style.display = 'inline-flex';

      }

      if(statusText) statusText.textContent = 'STOPPED';

      if(startTimeEl) startTimeEl.textContent = `(${jobState.durationStr})`;

    } else {

      if(statusBadge) {

        statusBadge.className = 'recipe-loaded';

        statusBadge.style.display = 'inline-flex';

      }

      if(statusText) statusText.textContent = 'READY';

      if(startTimeEl) startTimeEl.textContent = '';

    }

  }

}

