function startJob(recipe, operator, customStartTime){

  const startTime = customStartTime || new Date();

  jobState.active = true;

  jobState.startTime = startTime;

  jobState.endTime = null;

  jobState.durationStr = '';

  jobState.recipeId = recipe.id || '';

  jobState.recipeName = recipe.name || '';

  jobState.operator = operator || recipe.operator || '';



  try{

    localStorage.setItem('ricevision_job_state', JSON.stringify({

      active: true,

      startTime: startTime.toISOString(),

      recipeId: jobState.recipeId,

      recipeName: jobState.recipeName,

      operator: jobState.operator

    }));

  }catch(e){}



  fetch('/api/event', {

    method: 'POST',

    headers: { 'Content-Type': 'application/json' },

    body: JSON.stringify({

      event: 'JOB_STARTED',

      detail: `Job started for ${recipe.name}`,

      operator: jobState.operator,

      recipe: recipe.name

    })

  }).catch(()=>{});



  updateJobUI();

  // error.md Section 16.2: Reset the counters and bag tracking in startJob

  if (!HMI_STATE.report) HMI_STATE.report = {};

  HMI_STATE.report.counters = { '0-7': 0, '8-15': 0, '16-25': 0, over: 0, missed: 0, total: 0 };

  fbarxPost('/api/fbarx/cmd', { cmd: 'NEW JOB' });   // board + link counters start at zero

  window._lastSeenBagId = null;

  window._regStabilityBuf = [];

  window._lastCountedVal = null;

  window._noMatchCount = 0;

  if (typeof updateZoneCountersDisplay === 'function') updateZoneCountersDisplay();



  showToast(`JOB STARTED: ${jobState.recipeName} (${formatTime(startTime)})`);

}

