function endJob(){

  if(!jobState.active) return;

  const now = new Date();

  const startTime = jobState.startTime || now;

  const elapsedSec = Math.max(0, Math.round((now - startTime) / 1000));

  const mins = Math.floor(elapsedSec / 60);

  const secs = elapsedSec % 60;

  const durationStr = `${mins}m ${secs}s`;

  const recipeName = jobState.recipeName;

  const operator = jobState.operator;



  jobState.active = false;

  jobState.endTime = now;

  jobState.durationStr = durationStr;



  try{

    localStorage.removeItem('ricevision_job_state');

  }catch(e){}



  fetch('/api/event', {

    method: 'POST',

    headers: { 'Content-Type': 'application/json' },

    body: JSON.stringify({

      event: 'JOB_ENDED',

      detail: `Job ended. Duration: ${durationStr}`,

      operator: operator,

      recipe: recipeName

    })

  }).catch(()=>{});



  // Flush counts and job start/end time to production in SQLite DB

  const c = (HMI_STATE.report && HMI_STATE.report.counters) || { '0-7': 0, '8-15': 0, '16-25': 0, total: 0 };

  fetch('/api/production', {

    method: 'POST',

    headers: { 'Content-Type': 'application/json' },

    body: JSON.stringify({

      recipe: recipeName,

      operator: operator,

      start_time: startTime ? startTime.toISOString() : null,

      end_time: now.toISOString(),

      force: true,

      c0_7: Number(c['0-7']) || 0,

      c8_15: Number(c['8-15']) || 0,

      c16_25: Number(c['16-25']) || 0,

      c26_w: Number(c['26-window']) || 0,

      unscored: Number(c['unscored']) || 0,

      window_mm: Number(HMI_STATE.recipe?.markWindow) || null,

      total: Number(c['total']) || 0,

      band_edges: (window.HMI_STATE && window.HMI_STATE.stn2 && window.HMI_STATE.stn2.counterBands) ? window.HMI_STATE.stn2.counterBands : null,

      mark_window: (window.HMI_STATE && window.HMI_STATE.recipe && window.HMI_STATE.recipe.markWindow) ? window.HMI_STATE.recipe.markWindow : 40

    })

  }).then(() => {

    if(typeof fetchReportFromDB === 'function') fetchReportFromDB();

  }).catch(()=>{});



  const newRec = {

    dateTime: now.toISOString(),

    imageName: recipeName,

    operator: operator,

    c0_7: Number(c['0-7']) || 0,

    c8_15: Number(c['8-15']) || 0,

    c16_25: Number(c['16-25']) || 0,

    c26_w: Number(c['26-window']) || 0,

    unscored: Number(c['unscored']) || 0,

    windowMm: Number(HMI_STATE.recipe?.markWindow) || null,

    total: Number(c['total']) || 0,

    startTime: startTime ? startTime.toISOString() : null,

    endTime: now.toISOString()

  };

  if(!HMI_STATE.report) HMI_STATE.report = { records: [] };

  if(!Array.isArray(HMI_STATE.report.records)) HMI_STATE.report.records = [];

  HMI_STATE.report.records.unshift(newRec);



  if(HMI_STATE.report){

    HMI_STATE.report.endDateTime = now.toISOString().slice(0, 16);

    const repEnd = document.getElementById('report-disp-end');

    if(repEnd) repEnd.textContent = formatDateTime(now);

    const repEndInp = document.getElementById('report-end');

    if(repEndInp) repEndInp.value = now.toISOString().slice(0, 16);

    if(typeof updateReportScreen === 'function') updateReportScreen();

  }



  updateJobUI();

  showToast(`JOB ENDED — ${recipeName} (${durationStr})`);

}

