function applyRecipeToHmi(r){

  const rec=normalizeRecipe(r);

  HMI_STATE.recipe=rec;                                   // calibrate now edits a draft, so replacing the object is safe

  RecipeDB.setActive(rec.id);

  try{ const lite=Object.assign({},rec,{imageDataUrl:'',imageSig:null}); localStorage.setItem('recipeCalibration',JSON.stringify(lite)); }catch(e){}



  // 1. Dynamic brand name in header

  const el=document.getElementById('active-recipe-name');

  if(el) el.textContent=rec.name||'—';

  const camMatch=document.getElementById('cam-matched-name');

  if(camMatch) camMatch.textContent=(rec.name||'Veera Shivaji')+' (Front & Back)';



  // 2. Dynamic repeat & window

  const dispRepeat=document.getElementById('disp-repeat');

  if(dispRepeat) dispRepeat.textContent=rec.repeatLength;

  const dispWindow=document.getElementById('disp-window');

  if(dispWindow) dispWindow.textContent=rec.markWindow;



  // 3. Dynamic S-Tension target for Station 1

  if(rec.sTensionTarget != null){

    HMI_STATE.stn1.sTension = Number(rec.sTensionTarget);

  }



  // 4. Dynamic Mark offset for Station 2

  if(rec.markOffset != null){

    HMI_STATE.stn2.markOffset = Number(rec.markOffset);

  }



  // 5. Update DB Reference visual plate image

  updateDbRefPlate(rec);



  // 6. Update Calibration overlay static display elements

  updateCalOverlayFields(rec);



  // 7. Update Calibration screen if open

  if(typeof window.syncRecipeCalibrationUI === 'function') window.syncRecipeCalibrationUI();



  // 8. Update Report screen fields

  if(HMI_STATE.report){

    HMI_STATE.report.name = rec.name;

    HMI_STATE.report.imageName = rec.name;

    HMI_STATE.report.operator = rec.operator || HMI_STATE.report.operator || '';

    const rName = document.getElementById('report-name');

    if(rName) rName.value = rec.name;

    const rDispName = document.getElementById('report-disp-name');

    if(rDispName) rDispName.textContent = rec.name;

    const rOp = document.getElementById('report-operator');

    if(rOp) rOp.value = HMI_STATE.report.operator;

    const rDispOp = document.getElementById('report-disp-operator');

    if(rDispOp) rDispOp.textContent = HMI_STATE.report.operator || '—';

  }



  if(typeof refreshUI==='function') refreshUI();

}

const AlphaPad = (() => {

  const $=id=>document.getElementById(id);

  const rows = [

    ['1','2','3','4','5','6','7','8','9','0'],

    ['Q','W','E','R','T','Y','U','I','O','P'],

    ['A','S','D','F','G','H','J','K','L','-'],

    ['Z','X','C','V','B','N','M','.','/','BACK'],

    ['CLR','SPACE','_']

  ];

  let ctx=null, buf='', built=false, fresh=false;



  function show(){ const d=$('recipe-alpha-display'); if(!d) return; d.textContent = buf ? (buf.length>26 ? '…'+buf.slice(-25) : buf) : ' '; }



  function build(){

    if(built) return; built=true; const grid=$('recipe-alpha-grid'); grid.innerHTML='';

    rows.forEach(r => {

      r.forEach(k => {

        const b = document.createElement('button');

        b.type = 'button';

        if (k === 'BACK') {

          b.className = 'key-back';

          b.textContent = '⌫';

          b.title = 'Backspace';

          b.addEventListener('click', () => { fresh = false; buf = buf.slice(0, -1); show(); });

        } else if (k === 'CLR') {

          b.className = 'key-clr';

          b.textContent = 'CLR';

          b.title = 'Clear All';

          b.style.gridColumn = 'span 2';

          b.addEventListener('click', () => { fresh = false; buf = ''; show(); });

        } else if (k === 'SPACE') {

          b.textContent = 'SPACE';

          b.title = 'Space';

          b.style.gridColumn = 'span 6';

          b.addEventListener('click', () => {

            if (fresh) { buf = ''; fresh = false; }

            if (buf.length < (ctx?.max || 24)) { buf += ' '; show(); }

          });

        } else if (k === '_') {

          b.textContent = '_';

          b.style.gridColumn = 'span 2';

          b.addEventListener('click', () => {

            if (fresh) { buf = ''; fresh = false; }

            if (buf.length < (ctx?.max || 24)) { buf += '_'; show(); }

          });

        } else {

          b.textContent = k;

          b.addEventListener('click', () => {

            if (fresh) { buf = ''; fresh = false; }

            if (buf.length < (ctx?.max || 24)) { buf += k; show(); }

          });

        }

        grid.appendChild(b);

      });

    });



    $('recipe-alpha-cancel').addEventListener('click', close);

    $('recipe-alpha-ok').addEventListener('click', () => {

      const v = buf.trim(); if (ctx?.required && !v) return;

      const cb = ctx?.onOk; close(); if (cb) cb(v);

    });



    // Physical typing support for AlphaPad

    window.addEventListener('keydown', (e) => {

      const alphaModal = $('recipe-alpha-modal');

      if (!alphaModal || !alphaModal.classList.contains('open')) return;



      if (e.key === 'Escape') {

        e.preventDefault();

        close();

        return;

      }

      if (e.key === 'Enter') {

        e.preventDefault();

        $('recipe-alpha-ok')?.click();

        return;

      }

      if (e.key === 'Backspace') {

        e.preventDefault();

        fresh = false;

        buf = buf.slice(0, -1);

        show();

        return;

      }

      if (e.key === 'Delete') {

        e.preventDefault();

        fresh = false;

        buf = '';

        show();

        return;

      }

      if (e.key.length === 1 && !e.ctrlKey && !e.altKey && !e.metaKey) {

        e.preventDefault();

        if (fresh) { buf = ''; fresh = false; }

        if (buf.length < (ctx?.max || 24)) {

          buf += e.key.toUpperCase();

          show();

        }

      }

    });

  }



  function close(){ $('recipe-alpha-modal').classList.remove('open'); ctx=null; }

  function open(o){

    build(); ctx=o; buf=String(o.value||''); fresh=buf.length>0; $('recipe-alpha-title').textContent=o.title||'ENTER TEXT';

    const chips=$('recipe-alpha-chips'); chips.innerHTML='';

    (o.chips||[]).forEach(c=>{ const b=document.createElement('button'); b.type='button'; b.className='alpha-chip'; b.textContent=c;

      b.addEventListener('click',()=>{ fresh=false; buf=c; show(); }); chips.appendChild(b); });

    chips.style.display=(o.chips&&o.chips.length)?'flex':'none';

    show(); $('recipe-alpha-modal').classList.add('open');

  }

  return { open, close };

})();

