    const order = ['thangamayil', 'india', 'kohinoor', 'veera', 'royal'];

    const idxA = order.findIndex(k => (a.name || '').toLowerCase().includes(k));

    const idxB = order.findIndex(k => (b.name || '').toLowerCase().includes(k));

    return (idxA >= 0 ? idxA : 99) - (idxB >= 0 ? idxB : 99);

  });



  sel.innerHTML = all.map(r => {

    let displayName = r.name || '(no name)';

