function selectLoad(id, src, note){

  let r = RecipeDB.get(id);

  if(!r && id){

    r = RecipeDB.list().find(x => x.id === id || String(x.numericId) === String(id) || (x.name && x.name.toLowerCase() === String(id).toLowerCase()));

  }

  if(!r && RecipeDB.list().length > 0){

    r = RecipeDB.list().find(x => x.name && x.name.toLowerCase().includes('thangamayil')) || RecipeDB.list()[0];

  }

  if(!r) return;

  id = r.id;

  LS.sel = id;

  if(src) LS.src = src;



  const sel = $rl('recipe-select-name');

  if(sel) sel.value = id;



  const cards = [...document.querySelectorAll('#recipe-image-scroll .recipe-card')];

  cards.forEach(card => {

    const isThis = card.dataset.id === id;

    card.classList.toggle('active', isThis);

    let statusEl = card.querySelector('.recipe-card-status');

