      if(!statusEl){

        const info = card.querySelector('.recipe-card-info');

        if(info){

          statusEl = document.createElement('div');

          statusEl.className = 'recipe-card-status';

          statusEl.innerHTML = '<span class="status-dot-green"></span>MATCH CONFIRMED';

