async function showRecipeLoadScreen(){

  const screen = $rl('recipe-load-screen');

  if(!screen) return;

  const cur = HMI_STATE.recipe || {};

  LS.op = cur.operator || 'Operator 1';

  LS.src = 'NAME';



  if(typeof syncFromDatabase === 'function') await syncFromDatabase();

  populateRecipeSelectors();



  // Find Thangamayil or active recipe

  let start = null;

  const tm = RecipeDB.list().find(r => r.name && r.name.toLowerCase().includes('thangamayil'));

  if(tm) start = tm.id;

  else if(cur && cur.id && RecipeDB.get(cur.id)) start = cur.id;

  else start = (RecipeDB.list()[0] || {}).id;



  if(start) selectLoad(start, 'NAME'); else updateRecipeLoadStatus('DATABASE EMPTY');

  populateRecipeImages();



  // Reset camera & comparison UI

  stopLoadCamera();

  armDelete(false);

  const siftStatus = $rl('recipe-sift-status');

  if(siftStatus) { siftStatus.textContent = 'STANDBY'; siftStatus.style.color = '#f59e0b'; }

  const resMsg = $rl('recipe-compare-result');

  if(resMsg) { resMsg.textContent = 'Comparison not started.'; resMsg.style.color = '#475569'; }



  // Update clock & date immediately

  updateRecipeLoadClock();

  const alertEl = document.getElementById('recipe-load-off-alert');

  if (alertEl) alertEl.style.display = 'none';

  updateRecipeLoadStatus('READY — CONNECTED', true);



  screen.classList.add('open');

}

