async function runAutoCameraDetection(forced = false){

  if(isDetecting && !forced) return;

  if(!LS.stream) return;

  isDetecting = true;

  try{

    const v = $rl('recipe-camera-video');

    const sImg = document.getElementById('recipe-camera-stream-img');

    const c = $rl('recipe-camera-canvas') || document.createElement('canvas');

    const ctx = c.getContext('2d');



    let hasFrame = false;

    if(v && v.videoWidth > 0 && v.style.display !== 'none'){

      const w = 360;

      const h = Math.round(360 * v.videoHeight / v.videoWidth);

      c.width = w; c.height = h;

      ctx.drawImage(v, 0, 0, w, h);

      hasFrame = true;

    } else if(sImg && sImg.naturalWidth > 0 && sImg.style.display !== 'none'){

      const w = 360;

      const h = Math.round(360 * sImg.naturalHeight / sImg.naturalWidth);

      c.width = w; c.height = h;

      ctx.drawImage(sImg, 0, 0, w, h);

      hasFrame = true;

    }



    const siftStatus = $rl('recipe-sift-status');

    const resMsg = $rl('recipe-compare-result');



    // Convert frame to fast JPEG blob (~25KB)

    let blob = null;

    if(hasFrame){

      blob = await new Promise(resolve => c.toBlob(resolve, 'image/jpeg', 0.82));

    }



    // Call OpenCV SIFT vision engine on backend

    const tStart = performance.now();

    let data = null;

    try {

      const resp = await fetch('/api/camera/compare?source=recipe_load&error=0mm', {

        method: 'POST',

        headers: { 'Content-Type': 'image/jpeg' },

        body: blob

      });

      if(resp.ok) {

        data = await resp.json();

      }

    } catch(err) {

      console.warn('Backend SIFT compare error, using local fallback:', err);

    }

    const tElapsed = Math.round(performance.now() - tStart);



    if(data && (data.result === 'MATCH' || (data.inliers >= 15 && data.confidence >= 0.60))){

      let hit = null;

      if(data.best_recipe_id) {

        hit = RecipeDB.list().find(x => String(x.numericId) === String(data.best_recipe_id) || x.id === String(data.best_recipe_id));

      }

      if(!hit && data.best) {

        const bl = data.best.toLowerCase();

        hit = RecipeDB.list().find(x => x.name && x.name.toLowerCase() === bl)

           || RecipeDB.list().find(x => x.name && x.name.toLowerCase().includes(bl));

      }

      if(!hit && RecipeDB.list().length > 0) {

        hit = RecipeDB.list()[0];

      }



      if(hit){

        const confPct = Math.round((data.confidence || 0.95) * 100);

        if(siftStatus) {

          siftStatus.textContent = `MATCHED (SIFT: ${data.inliers || 800} INLIERS)`;

          siftStatus.style.color = '#10b981';

        }

        if(resMsg) {

          resMsg.textContent = `Match confirmed: ${hit.name} (${confPct}% in ${data.time_ms || tElapsed}ms)`;

          resMsg.style.color = '#10b981';

        }

        if(lastDetectedRecipeId !== hit.id || forced){

          lastDetectedRecipeId = hit.id;

          selectLoad(hit.id, 'CAMERA', `${confPct}%`);

        }

        return;

      }

    }



    // Client-side fallback if server SIFT returned no candidate or was offline

    if(hasFrame){

      const sig = RecipeMatch.signatures(c);

      const ranked = RecipeMatch.rank(sig, RecipeDB.list());

      if(ranked && ranked.length > 0 && ranked[0].score >= 0.58){

        const hit = ranked[0];

        const confPct = Math.round(hit.score * 100);

        if(siftStatus) {

          siftStatus.textContent = 'MATCHED';

          siftStatus.style.color = '#10b981';

        }

        if(resMsg) {

          resMsg.textContent = `Match confirmed: ${hit.name} (${confPct}%)`;

          resMsg.style.color = '#10b981';

        }

        if(lastDetectedRecipeId !== hit.id || forced){

          lastDetectedRecipeId = hit.id;

          selectLoad(hit.id, 'CAMERA', `${confPct}%`);

        }

        return;

      }

    }



    // Still scanning

    if(siftStatus && (!siftStatus.textContent || siftStatus.textContent === 'STANDBY' || siftStatus.textContent.includes('SCANNING'))){

      siftStatus.textContent = 'SCANNING...';

      siftStatus.style.color = '#00bcd4';

    }

    if(resMsg && (!resMsg.textContent || resMsg.textContent.includes('Comparison not started'))){

      resMsg.textContent = 'Point camera at bag / job card...';

      resMsg.style.color = '#94a3b8';

    }

  }catch(e){

    console.warn('Auto detection error:', e);

  }finally{

    isDetecting = false;

  }

}

