async function matchImageFile(file){

  if(!file) return;

  const siftStatus = $rl('recipe-sift-status');

  const resMsg = $rl('recipe-compare-result');

  if(siftStatus) { siftStatus.textContent = 'COMPARING (SIFT)...'; siftStatus.style.color = '#00bcd4'; }

  if(resMsg) { resMsg.textContent = 'Analyzing image with OpenCV SIFT...'; resMsg.style.color = '#00bcd4'; }

  try{

    // High-speed SIFT match on backend

    try {

      const resp = await fetch('/api/camera/compare?source=recipe_load_file&error=0mm', {

        method: 'POST',

        headers: { 'Content-Type': file.type || 'image/jpeg' },

        body: file

      });

      if(resp.ok) {

        const data = await resp.json();

        if(data && (data.result === 'MATCH' || data.inliers >= 15)){

          let hit = null;

          if(data.best_recipe_id) {

            hit = RecipeDB.list().find(x => String(x.numericId) === String(data.best_recipe_id) || x.id === String(data.best_recipe_id));

          }

          if(!hit && data.best) {

            const bl = data.best.toLowerCase();

            hit = RecipeDB.list().find(x => x.name && x.name.toLowerCase() === bl)

               || RecipeDB.list().find(x => x.name && x.name.toLowerCase().includes(bl));

          }

          if(hit){

            const confPct = Math.round((data.confidence || 0.95) * 100);

            selectLoad(hit.id, 'IMAGE', `${confPct}%`);

            if(siftStatus) { siftStatus.textContent = `MATCHED (SIFT: ${data.inliers || 800} INLIERS)`; siftStatus.style.color = '#10b981'; }

            if(resMsg) { resMsg.textContent = `Match confirmed: ${hit.name} (${confPct}% in ${data.time_ms || 150}ms)`; resMsg.style.color = '#10b981'; }

            return;

          }

        }

      }

    } catch(err) {

      console.warn('Server SIFT match failed, falling back to client match:', err);

    }



    // Local client-side fallback

    const url = await new Promise((ok,no)=>{ const fr=new FileReader(); fr.onload=()=>ok(fr.result); fr.onerror=()=>no(fr.error); fr.readAsDataURL(file); });

    const im = await RecipeMatch.loadImage(url);

    const ranked = RecipeMatch.rank(RecipeMatch.signatures(im), RecipeDB.list());

    if(ranked && ranked.length > 0){

      const hit = ranked[0];

      selectLoad(hit.id, 'IMAGE', `${Math.round(hit.score*100)}%`);

      if(siftStatus) { siftStatus.textContent = 'MATCHED'; siftStatus.style.color = '#10b981'; }

      if(resMsg) { resMsg.textContent = `Match confirmed: ${hit.name} (${Math.round(hit.score*100)}%)`; resMsg.style.color = '#10b981'; }

    } else {

      if(siftStatus) { siftStatus.textContent = 'NO MATCH'; siftStatus.style.color = '#ef4444'; }

      if(resMsg) { resMsg.textContent = 'No matching recipe found in database'; resMsg.style.color = '#ef4444'; }

    }

  }catch(e){

    console.warn('Match image file error:', e);

    if(siftStatus) { siftStatus.textContent = 'ERROR'; siftStatus.style.color = '#ef4444'; }

    if(resMsg) { resMsg.textContent = 'Could not read image file.'; resMsg.style.color = '#ef4444'; }

  }

}

