async function confirmRecipeLoad(){

  // Block recipe load if both stations are in OFF mode

  const s1Mode = String(window.HMI_STATE?.stn1?.mode || document.querySelector('#col-stn1 .mode-btn.active')?.dataset?.mode || 'OFF').toUpperCase();

  const s2Mode = String(window.HMI_STATE?.stn2?.mode || document.querySelector('#col-stn2 .mode-btn.active')?.dataset?.mode || 'OFF').toUpperCase();

  if (s1Mode === 'OFF' && s2Mode === 'OFF') {

    const msg = 'STATIONS IN OFF MODE — PLEASE TURN ON STN 1 OR STN 2 FIRST';

    const alertEl = document.getElementById('recipe-load-off-alert');

    if (alertEl) {

      alertEl.innerHTML = '&#9888; ' + msg;

      alertEl.style.display = 'block';

      clearTimeout(window._offAlertTimer);

      window._offAlertTimer = setTimeout(() => { if (alertEl) alertEl.style.display = 'none'; }, 5000);

    }

    const btn = document.getElementById('recipe-load-save');

    if (btn) {

      btn.style.outline = '2px solid #ef4444';

      setTimeout(() => { if (btn) btn.style.outline = ''; }, 1000);

    }

    if (typeof updateRecipeLoadStatus === 'function') {

      updateRecipeLoadStatus(msg, false, true);

    }

    if (typeof showToast === 'function') {

      showToast(msg, true);

    }

    return;

  }

  const alertEl = document.getElementById('recipe-load-off-alert');

  if (alertEl) alertEl.style.display = 'none';



  const base = RecipeDB.get(LS.sel);

  if(!base) return;

  base.operator = LS.op || base.operator;

  base.lastLoadedAt = Date.now();

  base.loadedVia = LS.src;

  const saved = await RecipeDB.save(base);

  applyRecipeToHmi(saved);



  // Record start time & show stop button on brand

  const startTime = new Date();

  startJob(saved, LS.op || saved.operator, startTime);



  // Sync load with backend API

  try{

    fetch('/api/load', {

      method: 'POST',

      headers: { 'Content-Type': 'application/json' },

      body: JSON.stringify({

        recipe_id: saved.numericId || (saved.id === 'seed-veera-sivaji' ? 1 : (saved.id === 'seed-thangamayil' ? 2 : (saved.id === 'seed-royal-bullet' ? 3 : 1))),

        operator: LS.op || saved.operator || 'Operator 1',

        source: LS.src || 'CAMERA'

      })

    }).then(r => r.json()).then(resp => {

      if (resp && resp.board && !resp.board.ok) showToast('BOARD NOT UPDATED: ' + Object.values(resp.board.errors).join('; '));

    }).catch(()=>{});

  }catch(e){}



  closeRecipeLoad();

  if(document.getElementById('screen-recipe')?.classList.contains('active') && window.beginRecipeEdit) window.beginRecipeEdit();

}

