async function save(){

  if(!draft) begin(); const d=draft;

  d.name=String(d.name||'').trim(); d.operator=String(d.operator||'').trim();

  if(!d.name){ status('RECIPE NAME REQUIRED — TAP RECIPE NAME',true); return; }

  if(!d.operator){ status('OPERATOR NAME REQUIRED — TAP OPERATOR',true); return; }

  const dup=RecipeDB.findByName(d.name);

  if(dup && dup.id!==d.id){

    d.id = dup.id;

    d.numericId = dup.numericId || d.numericId;

  }

  const btn=$('btn-save-recipe'); btn.disabled=true; status('SAVING TO DATABASE…');

  try{

    // 1. Persist recipe directly into SQLite DB via /api/recipes

    try {

      const payload = {

        recipe: {

          recipeId: d.numericId || undefined,

          name: d.name,

          brandTamil: d.brandTamil || '',

          product: d.product || '',

          netWeight: Number(d.netWeight) || 25,

          repeatLength: Number(d.repeatLength) || 740,

          width: Number(d.width) || 495,

          material: d.material || 'BOPP',

          markWindow: Number(d.markWindow) || 40,

          markOffset: Number(d.markOffset) || 0,

          sTensionTarget: Number(d.sTensionTarget) || 5.0,

          frontSensor: Number(d.frontSensor) || 0,

          backSensor: Number(d.backSensor) || 0,

          frontMark: Number(d.frontMark) || 0,

          frontBackground: Number(d.frontBackground) || 0,

          backMark: Number(d.backMark) || 0,

          backBackground: Number(d.backBackground) || 0

        },

        operator: d.operator,

        image: (d.imageDataUrl && d.imageDataUrl.startsWith('data:')) ? { dataUrl: d.imageDataUrl, name: d.imageName || (d.name + '.jpg') } : (d.frontImageDataUrl && d.frontImageDataUrl.startsWith('data:') ? { dataUrl: d.frontImageDataUrl, name: d.frontImageName || (d.name + '_front.jpg') } : undefined),

        frontImage: (d.frontImageDataUrl && d.frontImageDataUrl.startsWith('data:')) ? { dataUrl: d.frontImageDataUrl, name: d.frontImageName || (d.name + '_front.jpg') } : undefined,

        backImage: (d.backImageDataUrl && d.backImageDataUrl.startsWith('data:')) ? { dataUrl: d.backImageDataUrl, name: d.backImageName || (d.name + '_back.jpg') } : undefined

      };

      const res = await fetch('/api/recipes', {

        method: 'POST',

        headers: { 'Content-Type': 'application/json' },

        body: JSON.stringify(payload)

      });

      if (res.ok) {

        const resp = await res.json();

        if (resp && resp.recipe) {

          d.numericId = resp.recipe.recipeId;

          if (resp.recipe.imageUrl) { d.imageUrl = resp.recipe.imageUrl; d.imageDataUrl = resp.recipe.imageUrl; }

          if (resp.recipe.frontImageUrl) d.frontImageUrl = resp.recipe.frontImageUrl;

          if (resp.recipe.backImageUrl) d.backImageUrl = resp.recipe.backImageUrl;

        }

      }

    } catch(eB) {

      console.warn('Backend /api/recipes save error:', eB);

    }



    // 2. Persist locally in RecipeDB

    const saved=await RecipeDB.save(d);

    applyRecipeToHmi(saved);



    // 3. Immediately refresh selectors so Recipe Load screen lists the added recipe

    populateCalRecipeSelect();

    if (typeof populateRecipeSelectors === 'function') populateRecipeSelectors();

    if (typeof populateRecipeImages === 'function') populateRecipeImages();



    draft=null; recipeEditSnapshot=null;

    if (typeof showToast === 'function') showToast(`RECIPE "${saved.name}" SAVED TO DATABASE`);

    returnToHomeScreen();

  }catch(e){ status('DATABASE SAVE FAILED — '+(e&&e.name||'ERROR'),true); }

  finally{ btn.disabled=false; }

}

