  document.querySelectorAll('[data-recipe-num]').forEach(el=>el.addEventListener('click',()=>openRecipeNumpad(el.dataset.recipeNum)));

  $('recipe-name-field').addEventListener('click',()=>editText('name','RECIPE NAME',24,{required:true}));

  $('recipe-operator-field').addEventListener('click',()=>editText('operator','OPERATOR NAME — TAP A SAVED NAME OR TYPE A NEW ONE',24,{required:true,chips:RecipeDB.operators()}));

  $('recipe-product-field').addEventListener('click',()=>editText('product','PRODUCT / VARIETY',48));

  $('recipe-notes-field').addEventListener('click',()=>editText('notes','NOTES',60));

  document.querySelectorAll('input[name="recipe-material"]').forEach(el=>el.addEventListener('change',()=>{ if(!draft) begin(); draft.material=el.value; status('MATERIAL UPDATED — NOT SAVED YET'); }));

  ['front-mark','front-bg','back-mark','back-bg'].forEach(key=>{

    const el=$('recipe-'+key); if(!el) return;

    el.addEventListener('click',()=>{

      if(!draft) begin();

      const back=key.indexOf('back-')===0, mark=key.endsWith('mark'), value=Math.floor(Math.random()*65536);   // simulated sensor read, as before

      if(back){ draft.backSensor=value; if(mark) draft.backMark=value; else draft.backBackground=value; }

      else { draft.frontSensor=value; if(mark) draft.frontMark=value; else draft.frontBackground=value; }

      sync(); status((back?'BACK':'FRONT')+' '+(mark?'MARK':'BACKGROUND')+' CAPTURED');

    });

  });



  const calSel = $('cal-recipe-select');

  if(calSel){

    calSel.addEventListener('change', () => {

      const val = calSel.value;

      if(val){

        const rec = RecipeDB.get(val);

        if(rec){

          draft = normalizeRecipe(rec);

          sync();

          status(`EDITING: ${draft.name||'(unnamed)'} — CHANGES SAVE TO DATABASE`);

        }

      }

    });

  }

  const btnNew = $('recipe-new-btn');

  if(btnNew) btnNew.addEventListener('click', blank);



  let filePreviewMode = 'dual'; // 'dual' | 'single'

  let pendingFileFront = null;

  let pendingFileFrontName = '';

  let pendingFileBack = null;

  let pendingFileBackName = '';

  let pendingFileSingle = null;

  let pendingFileSingleName = '';

  let pendingFileSingleTarget = 'front'; // 'front' | 'back'



  function showSingleFilePreview(dataUrl, name, target){

    if(!draft) begin();

    filePreviewMode = 'single';

    pendingFileSingle = dataUrl;

    pendingFileSingleName = name;

    pendingFileSingleTarget = target;



    const titleEl = $('file-preview-title');

    const badgeEl = $('file-preview-badge');

    const labelEl = $('file-preview-single-label');

    const imgEl = $('file-preview-single-img');

    const nameEl = $('file-preview-single-name');

    const dualWrap = $('file-preview-dual-wrap');

    const singleWrap = $('file-preview-single-wrap');

    const modal = $('recipe-file-preview-modal');



    const isBack = target === 'back';

    if(titleEl) titleEl.textContent = `PREVIEW ${isBack ? 'BACK' : 'FRONT'} IMAGE — CHECK IF CORRECT`;

    if(badgeEl) { badgeEl.textContent = isBack ? 'BACK VIEW' : 'FRONT VIEW'; badgeEl.style.color = isBack ? 'var(--amber-bright)' : 'var(--cyan-bright)'; }

    if(labelEl) { labelEl.textContent = isBack ? 'BACK SIDE ARTWORK' : 'FRONT SIDE ARTWORK'; labelEl.style.color = isBack ? 'var(--amber-bright)' : 'var(--cyan-bright)'; }

    if(imgEl) imgEl.src = dataUrl;

    if(nameEl) nameEl.textContent = name;

    if(dualWrap) dualWrap.style.display = 'none';

    if(singleWrap) singleWrap.style.display = 'flex';

    if(modal) modal.classList.add('open');

    status(`PREVIEWING ${isBack ? 'BACK' : 'FRONT'} IMAGE — VERIFY AND CONFIRM`);

  }



  function showDualFilePreview(frontDataUrl, frontName, backDataUrl, backName){

    if(!draft) begin();

    filePreviewMode = 'dual';

    pendingFileFront = frontDataUrl;

    pendingFileFrontName = frontName;

    pendingFileBack = backDataUrl;

    pendingFileBackName = backName;



    const titleEl = $('file-preview-title');

    const badgeEl = $('file-preview-badge');

    const fImg = $('file-preview-front-img');

    const fName = $('file-preview-front-name');

    const bImg = $('file-preview-back-img');

    const bName = $('file-preview-back-name');

    const dualWrap = $('file-preview-dual-wrap');

    const singleWrap = $('file-preview-single-wrap');

    const modal = $('recipe-file-preview-modal');



    if(titleEl) titleEl.textContent = 'PREVIEW UPLOADED IMAGES — CHECK IF CORRECT';

    if(badgeEl) { badgeEl.textContent = 'FRONT & BACK'; badgeEl.style.color = 'var(--amber-bright)'; }

    if(fImg) fImg.src = frontDataUrl;

    if(fName) fName.textContent = frontName;

    if(bImg) bImg.src = backDataUrl;

    if(bName) bName.textContent = backName;

    if(dualWrap) dualWrap.style.display = 'grid';

    if(singleWrap) singleWrap.style.display = 'none';

    if(modal) modal.classList.add('open');

    status('CHECK IF CORRECT IMAGES ARE UPLOADED — TAP CONFIRM TO APPLY');

  }



  // Single Front File Selection

  const fileFront = $('recipe-front-file-input');

  const btnFront = $('recipe-front-btn');

  if (btnFront && fileFront) {

    btnFront.addEventListener('click', () => { fileFront.value = ''; fileFront.click(); });

    fileFront.addEventListener('change', () => {

      const f = fileFront.files && fileFront.files[0];

      if (!f) return;

      const fr = new FileReader();

      fr.onload = () => {

        const dataUrl = fr.result;

        const img = new Image();

        img.onload = () => {

          if (img.width > img.height * 1.1) {

            // Wide image with dual sides

            const halfW = Math.floor(img.width / 2);

            const cFront = document.createElement('canvas');

            cFront.width = halfW; cFront.height = img.height;

            cFront.getContext('2d').drawImage(img, 0, 0, halfW, img.height, 0, 0, halfW, img.height);

            const cBack = document.createElement('canvas');

            cBack.width = img.width - halfW; cBack.height = img.height;

            cBack.getContext('2d').drawImage(img, halfW, 0, img.width - halfW, img.height, 0, 0, img.width - halfW, img.height);

            showDualFilePreview(cFront.toDataURL('image/jpeg', 0.9), f.name + ' (Front)', cBack.toDataURL('image/jpeg', 0.9), f.name + ' (Back)');

          } else {

            showSingleFilePreview(dataUrl, f.name, 'front');

          }

        };

        img.src = dataUrl;

      };

      fr.readAsDataURL(f);

    });

  }



  // Single Back File Selection

  const fileBack = $('recipe-back-file-input');

  const btnBack = $('recipe-back-btn');

  if (btnBack && fileBack) {

    btnBack.addEventListener('click', () => { fileBack.value = ''; fileBack.click(); });

    fileBack.addEventListener('change', () => {

      const f = fileBack.files && fileBack.files[0];

      if (!f) return;

      const fr = new FileReader();

      fr.onload = () => showSingleFilePreview(fr.result, f.name, 'back');

      fr.readAsDataURL(f);

    });

  }



  // Sequential LOAD BOTH F+B Workflow: Front File -> then Back File -> Preview Both

  const fileFbFront = $('recipe-fb-front-input');

  const fileFbBack = $('recipe-fb-back-input');

  const btnFbBoth = $('recipe-image-btn');



  if (btnFbBoth && fileFbFront && fileFbBack) {

    btnFbBoth.addEventListener('click', () => {

      pendingFileFront = null;

      pendingFileBack = null;

      fileFbFront.value = '';

      fileFbBack.value = '';

      status('STEP 1: SELECT FRONT SIDE IMAGE FROM FILES...');

      fileFbFront.click();

    });



    fileFbFront.addEventListener('change', () => {

      const f1 = fileFbFront.files && fileFbFront.files[0];

      if (!f1) return;

      const fr1 = new FileReader();

      fr1.onload = () => {

        const dataUrl = fr1.result;

        const img = new Image();

        img.onload = () => {

          if (img.width > img.height * 1.1) {

            // Dual side image detected automatically

            const halfW = Math.floor(img.width / 2);

            const cFront = document.createElement('canvas');

            cFront.width = halfW; cFront.height = img.height;

            cFront.getContext('2d').drawImage(img, 0, 0, halfW, img.height, 0, 0, halfW, img.height);

            const cBack = document.createElement('canvas');

            cBack.width = img.width - halfW; cBack.height = img.height;

            cBack.getContext('2d').drawImage(img, halfW, 0, img.width - halfW, img.height, 0, 0, img.width - halfW, img.height);

            showDualFilePreview(cFront.toDataURL('image/jpeg', 0.9), f1.name + ' (Front)', cBack.toDataURL('image/jpeg', 0.9), f1.name + ' (Back)');

          } else {

            pendingFileFront = dataUrl;

            pendingFileFrontName = f1.name;

            status(`FRONT LOADED: "${f1.name}". STEP 2: SELECT BACK SIDE IMAGE...`);

            if (typeof showToast === 'function') showToast('FRONT IMAGE SELECTED. NOW SELECT BACK SIDE IMAGE');

            setTimeout(() => fileFbBack.click(), 260);

          }

        };

        img.src = dataUrl;

      };

      fr1.readAsDataURL(f1);

    });



    fileFbBack.addEventListener('change', () => {

      const f2 = fileFbBack.files && fileFbBack.files[0];

      if (!f2) {

        if (pendingFileFront) showSingleFilePreview(pendingFileFront, pendingFileFrontName, 'front');

        return;

      }

      const fr2 = new FileReader();

      fr2.onload = () => {

        showDualFilePreview(pendingFileFront, pendingFileFrontName, fr2.result, f2.name);

      };

      fr2.readAsDataURL(f2);

    });

  }



  // Confirmation & Cancel for File Preview Modal

  const btnFileConfirm = $('file-preview-confirm');

  const btnFileCancel = $('file-preview-cancel');

  if (btnFileConfirm) {

    btnFileConfirm.addEventListener('click', () => {

      if (!draft) begin();

      if (filePreviewMode === 'dual') {

        draft.frontImageDataUrl = pendingFileFront;

        draft.frontImageName = pendingFileFrontName;

        draft.backImageDataUrl = pendingFileBack;

        draft.backImageName = pendingFileBackName;

        draft.imageDataUrl = pendingFileFront;

        draft.imageName = pendingFileFrontName;

        sync();

        $('recipe-file-preview-modal').classList.remove('open');

        if (typeof showToast === 'function') showToast('FRONT & BACK ARTWORKS LOADED');

        status('FRONT & BACK LOADED — SAVE & EXIT TO UPDATE DATABASE');

      } else if (filePreviewMode === 'single') {

        if (pendingFileSingleTarget === 'back') {

          draft.backImageDataUrl = pendingFileSingle;

          draft.backImageName = pendingFileSingleName;

          sync();

          $('recipe-file-preview-modal').classList.remove('open');

          if (typeof showToast === 'function') showToast('BACK VIEW LOADED');

          status('BACK VIEW LOADED — SAVE & EXIT TO UPDATE DATABASE');

        } else {

          draft.frontImageDataUrl = pendingFileSingle;

          draft.frontImageName = pendingFileSingleName;

          if (!draft.imageDataUrl) {

            draft.imageDataUrl = pendingFileSingle;

            draft.imageName = pendingFileSingleName;

          }

          sync();

          $('recipe-file-preview-modal').classList.remove('open');

          if (typeof showToast === 'function') showToast('FRONT VIEW LOADED');

          status('FRONT VIEW LOADED — SAVE & EXIT TO UPDATE DATABASE');

        }

      }

    });

  }

  if (btnFileCancel) {

    btnFileCancel.addEventListener('click', () => {

      $('recipe-file-preview-modal').classList.remove('open');

      pendingFileFront = null; pendingFileBack = null; pendingFileSingle = null;

      status('IMAGE SELECTION CANCELLED — NO CHANGES APPLIED');

    });

  }



  // Camera Capture Buttons & Actions

  const btnFrontCam = $('recipe-front-cam-btn');

  if (btnFrontCam) btnFrontCam.addEventListener('click', () => openCapture('front'));



  const btnBackCam = $('recipe-back-cam-btn');

  if (btnBackCam) btnBackCam.addEventListener('click', () => openCapture('back'));



  const btnBothCam = $('recipe-image-cam-btn');

  if (btnBothCam) btnBothCam.addEventListener('click', () => openCapture('both'));



  const btnCamRetake = $('recipe-cam-retake');

  if (btnCamRetake) btnCamRetake.addEventListener('click', retakeCapture);



  const btnCamConfirm = $('recipe-cam-confirm');

  if (btnCamConfirm) btnCamConfirm.addEventListener('click', confirmCapture);



  const btnCamRetakeCancel = $('recipe-cam-retake-cancel');

  if (btnCamRetakeCancel) btnCamRetakeCancel.addEventListener('click', closeCapture);



  $('recipe-cam-cancel').addEventListener('click', closeCapture);

  $('recipe-cam-shoot').addEventListener('click', shoot);

  $('recipe-new-btn')?.addEventListener('click', blank);

  $('recipe-db-load-btn')?.addEventListener('click', showRecipeLoadScreen);



  const btnDel = $('btn-delete-recipe');

  if (btnDel) {

    btnDel.onclick = openDeleteRecipeModal;

    btnDel.addEventListener('click', openDeleteRecipeModal);

  }

  const btnDelConfirm = $('recipe-delete-confirm-btn');

  if (btnDelConfirm) btnDelConfirm.onclick = performDeleteRecipe;

  const btnDelCancel = $('recipe-delete-cancel-btn');

  if (btnDelCancel) btnDelCancel.onclick = () => $('recipe-delete-modal').classList.remove('open');

}

