async function syncFromDatabase() {

  console.log('[SYNC] Connecting to SQLite DB via server endpoints...');

  try {

    // 1. Fetch recipes from DB (/api/recipes)

    const recRes = await fetch('/api/recipes');

    if (recRes.ok) {

      const dbRecipes = await recRes.json();

      if (Array.isArray(dbRecipes) && dbRecipes.length > 0) {

        for (const locR of RecipeDB.list()) {

          if (locR.numericId && !dbRecipes.some(r => r.recipeId === locR.numericId)) {

            await RecipeDB.remove(locR.id);

          }

        }

        for (const dbR of dbRecipes) {

          const existing = RecipeDB.list().find(r => r.name.toLowerCase() === dbR.name.toLowerCase() || (dbR.recipeId && r.numericId === dbR.recipeId));

          const recNorm = {

            id: existing ? existing.id : 'db-' + (dbR.recipeId || dbR.name.toLowerCase().replace(/\s+/g, '-')),

            numericId: dbR.recipeId || (existing ? existing.numericId : null),

            name: dbR.name,

            brandTamil: dbR.brandTamil || (existing ? existing.brandTamil : ''),

            product: dbR.product || dbR.name,

            operator: dbR.operator || (existing ? existing.operator : 'Operator 1'),

            imageUrl: dbR.imageUrl || dbR.frontImageUrl || '',

            frontImageUrl: dbR.frontImageUrl || dbR.imageUrl || '',

            backImageUrl: dbR.backImageUrl || '',

            frontImageName: dbR.frontImageName || dbR.name,

            backImageName: dbR.backImageName || '',

            repeatLength: Number(dbR.repeatLength) || 740,

            width: Number(dbR.width) || 495,

            material: dbR.material || 'BOPP',

            markWindow: Number(dbR.markWindow) || 40,

            markOffset: Number(dbR.markOffset) || 0,

            sTensionTarget: Number(dbR.sTensionTarget) || 5.0,

            frontSensor: Number(dbR.frontSensor) || 0,

            backSensor: Number(dbR.backSensor) || 0,

            netWeight: Number(dbR.netWeight) || (existing ? existing.netWeight : 25)

          };

          recNorm.imageDataUrl = recNorm.frontImageUrl || recNorm.imageUrl || (existing ? existing.imageDataUrl : '');

          await RecipeDB.save(recNorm);

        }

        console.log(`[SYNC] Synced ${dbRecipes.length} recipes from SQLite DB.`);

      }

    }

  } catch(e) { console.warn('[SYNC] Could not sync recipes from /api/recipes', e); }



  try {

    // 2. Fetch operators from DB (/api/operators)

    const opRes = await fetch('/api/operators');

    if (opRes.ok) {

      const dbOps = await opRes.json();

      if (Array.isArray(dbOps)) {

        dbOps.forEach(o => {

          if (o && o.name) RecipeDB.addOperator(o.name);

        });

        console.log(`[SYNC] Synced ${dbOps.length} operators from SQLite DB.`);

      }

    }

  } catch(e) {}



  try {

    // 3. Fetch current system state (/api/state)

    const stRes = await fetch('/api/state');

    if (stRes.ok) {

      const st = await stRes.json();

      if (st && st.recipe) {

        const matching = RecipeDB.findByName(st.recipe.name);

        if (matching) {

          if (st.operator) matching.operator = st.operator;

          applyRecipeToHmi(matching);

        }

      }

    }

  } catch(e) {}



  try {

    // 4. Fetch production report records from DB (/api/report)

    await fetchReportFromDB();

  } catch(e) {}



  if (typeof populateRecipeSelectors === 'function') populateRecipeSelectors();

  if (typeof populateRecipeImages === 'function') populateRecipeImages();

  if (typeof populateReportDropdowns === 'function') populateReportDropdowns();

}

