async function fetchReportFromDB() {

  try {

    const res = await fetch('/api/report');

    if (res.ok) {

      const records = await res.json();

      if (Array.isArray(records)) {

        if (!HMI_STATE.report) HMI_STATE.report = { records: [] };

        HMI_STATE.report.records = records;

        if (records.length > 0) {

          const latest = records[0];

          if (latest.startTime) {

            const rStart = document.getElementById('report-disp-start');

            if (rStart) rStart.textContent = formatDateTime(new Date(latest.startTime));

          }

          if (latest.endTime) {

            const rEnd = document.getElementById('report-disp-end');

            if (rEnd) rEnd.textContent = formatDateTime(new Date(latest.endTime));

          }

        }

        if (typeof populateReportDropdowns === 'function') populateReportDropdowns();

        if (typeof updateReportScreen === 'function') updateReportScreen();

        console.log(`[SYNC] Loaded ${records.length} production report records from SQLite DB.`);

      }

    }

  } catch(e) { console.warn('[SYNC] Failed to fetch /api/report', e); }

}

