function recordBagInBin(binName, force = false) {

  if (!window.HMI_STATE) return;

  if (window._fbarxPollOk) return;     // counts come from the link

  // error.md Section 16.2: Count only while jobState.active is true (unless force is passed)

  if (!force && typeof jobState !== 'undefined' && !jobState.active) {

    return;

  }

  if (!window.HMI_STATE.report) window.HMI_STATE.report = { counters: { '0-7': 0, '8-15': 0, '16-25': 0, over: 0, missed: 0, total: 0 } };

  const counters = window.HMI_STATE.report.counters;

  if (counters[binName] !== undefined) {

    counters[binName] = (counters[binName] || 0) + 1;

  }

  counters.total = (counters.total || 0) + 1;

  updateZoneCountersDisplay();

}

