function updateErrorPercentageDisplay(data) {

  if (!data) return;



  const hasBagId = (typeof data.bag_id !== 'undefined' && data.bag_id !== null);

  const isNoMatch = (data.ok === false) || (data.status === 'NO MATCH') || (typeof data.confidence === 'number' && data.confidence < 0.60);



  // 1. Trigger-based counting per new bag_id (error.md Section 10 & 16.6)

  if (hasBagId) {

    if (data.bag_id !== window._lastSeenBagId) {

      window._lastSeenBagId = data.bag_id;

      if (isNoMatch) {

        // Missed bag: logged so bins + over + missed = total (error.md Section 10.3)

        recordBagInBin('missed');

      } else {

        const dyMm = (typeof data.offset_y_mm === 'number') ? data.offset_y_mm : ((typeof data.error_mm === 'number') ? data.error_mm : 0.0);

        const regErrMm = (typeof data.reg_err_mm === 'number') ? data.reg_err_mm : Math.abs(dyMm);

        const bin = data.bin || (regErrMm <= 7.0 ? '0-7' : (regErrMm <= 15.0 ? '8-15' : (regErrMm <= 25.0 ? '16-25' : 'over')));

        recordBagInBin(bin);

      }

    }

  }



  if (isNoMatch) {

    // Per error.md Section 13 & 15: If confidence < 0.60 or no match, show NO MATCH

    const fullStat = document.getElementById('full-cam-reg-stat');

    if (fullStat) {

      fullStat.textContent = 'REGISTRATION: NO MATCH (CONF < 0.60)';

      fullStat.style.color = '#8b949e';

    }

    const errBadgeEl = document.getElementById('cam-error-status-badge');

    if (errBadgeEl) {

      errBadgeEl.textContent = 'NO MATCH';

      errBadgeEl.style.color = '#8b949e';

      errBadgeEl.style.background = '#161b22';

      errBadgeEl.style.borderColor = '#30363d';

    }

    const errValEl = document.getElementById('cam-error-pct-val');

    if (errValEl) {

      errValEl.textContent = '--';

      errValEl.style.color = '#8b949e';

    }

    const hudPill = document.getElementById('hud-error-pill');

    if (hudPill) {

      hudPill.textContent = 'ALIGNMENT: 0.0mm • DISTANCE: NO MATCH';

      hudPill.style.color = '#8b949e';

      hudPill.style.borderColor = '#30363d';

      hudPill.style.background = 'rgba(5,8,12,0.92)';

    }

    if (!hasBagId) {

      window._noMatchCount = (window._noMatchCount || 0) + 1;

      if (window._noMatchCount >= 2) {

        window._lastCountedVal = null;

        window._regStabilityBuf = [];

      }

    }

    return;

  }



  const dyMm = (typeof data.offset_y_mm === 'number') ? data.offset_y_mm : ((typeof data.error_mm === 'number') ? data.error_mm : 0.0);

  const dxMm = (typeof data.offset_x_mm === 'number') ? data.offset_x_mm : 0.0;

  const regErrMm = (typeof data.reg_err_mm === 'number') ? data.reg_err_mm : Math.abs(dyMm);



  // Bin classification and tolerances from error.md Section 9:

  // 0 .. 7mm -> "0-7" (PASS, green)

  // 8 .. 15mm -> "8-15" (FAIL, amber)

  // 16 .. 25mm -> "16-25" (FAIL, red)

  // > 25mm -> "over" (FAIL, red)

  const bin = data.bin || (regErrMm <= 7.0 ? '0-7' : (regErrMm <= 15.0 ? '8-15' : (regErrMm <= 25.0 ? '16-25' : 'over')));

  const isPass = (regErrMm <= 7.0);

  const statusText = isPass ? 'PASS (IN SPEC)' : 'FAIL (OUT OF SPEC)';



  let color = '#2ea043';

  let badgeBg = '#0d2217';

  let badgeBdr = '#2ea043';

  if (bin === '8-15') {

    color = '#d29922';

    badgeBg = '#2e2305';

    badgeBdr = '#d29922';

  } else if (bin === '16-25' || bin === 'over' || !isPass) {

    color = '#f85149';

    badgeBg = '#2b1012';

    badgeBdr = '#da3633';

  }



  const errSign = dyMm > 0 ? '+' : '';

  const errMmStr = (Math.abs(dyMm) < 0.05) ? '0.0 mm' : `${errSign}${dyMm.toFixed(1)} mm`;



  // 1. Error main readout in MM on Screen 2 inspection panel

  const errValEl = document.getElementById('cam-error-pct-val');

  if (errValEl) {

    errValEl.textContent = errMmStr;

    errValEl.style.color = color;

  }

  const errBadgeEl = document.getElementById('cam-error-status-badge');

  if (errBadgeEl) {

    errBadgeEl.textContent = statusText;

    errBadgeEl.style.color = color;

    errBadgeEl.style.background = badgeBg;

    errBadgeEl.style.borderColor = badgeBdr;

  }

  const errBarEl = document.getElementById('cam-error-bar');

  if (errBarEl) {

    const barPct = Math.min(100, Math.max(2, (regErrMm / 20.0) * 100));

    errBarEl.style.width = barPct + '%';

    errBarEl.style.background = color;

  }

  const subOffset = document.getElementById('cam-error-offset-sub');

  if (subOffset) subOffset.textContent = `ΔY: ${errSign}${dyMm.toFixed(1)}mm`;

  // error.md Section 16.3: Separately label PASS specification limit and recipe mark window

  const recWin = Math.round(((window.HMI_STATE?.recipe?.markWindow || 40) / 2));

  const subWin = document.getElementById('cam-error-win-sub');

  if (subWin) subWin.textContent = `PASS: ±7.0mm • WIN: ±${recWin}mm`;



  // 2. HUD Centerline Error Pill (show in MM)

  const hudPill = document.getElementById('hud-error-pill');

  if (hudPill) {

    const dyStr = (dyMm > 0 ? '+' : '') + dyMm.toFixed(1) + 'mm';

    hudPill.textContent = `ALIGNMENT: ${dyStr} • DISTANCE: ${errMmStr}`;

    hudPill.style.color = color;

    hudPill.style.borderColor = color;

    hudPill.style.background = isPass ? 'rgba(5,8,12,0.92)' : (bin === '8-15' ? 'rgba(25,20,5,0.92)' : 'rgba(30,10,12,0.92)');

  }



  // 3. Print Registration Offset Tile (error.md Section 11, 13.1, 16.5: show corr_mm)

  const offsetEl = document.getElementById('cam-reg-offset-val');

  if (offsetEl) {

    const dy = (dyMm > 0 ? '+' : '') + dyMm.toFixed(1) + 'mm';

    const dx = (dxMm > 0 ? '+' : '') + dxMm.toFixed(1) + 'mm';

    const corrVal = (typeof data.corr_mm === 'number') ? `${data.corr_mm > 0 ? '+' : ''}${data.corr_mm.toFixed(1)}mm` : '0.0mm';

    offsetEl.textContent = `ΔX:${dx} • ΔY:${dy} • CORR:${corrVal}`;

    offsetEl.style.color = color;

  }



  // 4. SIFT / ORB Template Confidence

  const confEl = document.getElementById('cam-conf-val');

  if (confEl && typeof data.confidence === 'number') {

    confEl.innerHTML = `${data.confidence.toFixed(2)}`;

    confEl.style.color = isPass ? '#7ee787' : color;

  }



  // 5. HUD Stats Bar & Latency (error.md Section 12, 13.1)

  const statEl = document.getElementById('full-cam-reg-stat');

  if (statEl) {

    const dy = (dyMm > 0 ? '+' : '') + dyMm.toFixed(1) + 'mm';

    statEl.textContent = `REGISTRATION: ${dy} (${data.status || statusText}) • ERROR: ${errMmStr}`;

    statEl.style.color = color;

  }

  const fpsStatEl = document.getElementById('full-cam-fps-stat');

  if (fpsStatEl && typeof data.latency_ms === 'number') {

    fpsStatEl.textContent = `FPS: 30.0 • LATENCY: ${data.latency_ms}ms`;

  }



  // 6. HUD Boxes

  const boxF = document.querySelector('#hud-box-front .bbox-label');

  if (boxF) boxF.textContent = `FRONT: 0.0mm (REF)`;

  const boxB = document.querySelector('#hud-box-back .bbox-label');

  if (boxB) {

    const dy = (dyMm > 0 ? '+' : '') + dyMm.toFixed(1) + 'mm';

    boxB.textContent = `BACK: ${dy} (ERR: ${errMmStr})`;

    boxB.style.background = color;

  }

  const boxBContainer = document.getElementById('hud-box-back');

  if (boxBContainer) {

    const baseTop = 4.0;

    // error.md Section 16.1: Positive error = back panel is lower (larger top percentage)

    const shiftPct = baseTop + (dyMm * 0.25);

    boxBContainer.style.top = Math.max(1.0, Math.min(8.0, shiftPct)) + '%';

    boxBContainer.style.borderColor = color;

    boxBContainer.style.boxShadow = isPass ? '0 0 10px rgba(46,160,67,0.35)' : '0 0 10px rgba(248,81,73,0.35)';

  }



  // 7. Update Screen 1 Mini Cam Badges

  const liveErrBadge = document.getElementById('live-cam-err-badge');

  if (liveErrBadge) {

    const dy = (dyMm > 0 ? '+' : '') + dyMm.toFixed(1) + 'mm';

    liveErrBadge.textContent = `REG: ${dy} (ERR: ${errMmStr})`;

    liveErrBadge.style.color = color;

    liveErrBadge.style.borderColor = badgeBdr;

    liveErrBadge.style.background = badgeBg;

  }

  const liveCamPct = document.getElementById('recipe-live-cam-pct');

  if (liveCamPct) {

    liveCamPct.textContent = `ERR: ${errMmStr}`;

    liveCamPct.style.color = color;

  }



  // 8. UPDATE MARK WINDOW WITH ERROR IN MM (ruler, needle, m1, m2, active chip)

  updateMarkWindowWithError(dyMm);



  // 9. Fallback counting when no trigger exists (error.md Section 10 Fallback)

  if (!hasBagId) {

    window._regStabilityBuf = window._regStabilityBuf || [];

    window._lastCountedVal = window._lastCountedVal ?? null;

    window._noMatchCount = 0;

    window._regStabilityBuf.push(dyMm);

    if (window._regStabilityBuf.length > 3) window._regStabilityBuf.shift();

    if (window._regStabilityBuf.length === 3) {

      const minVal = Math.min(...window._regStabilityBuf);

      const maxVal = Math.max(...window._regStabilityBuf);

      if ((maxVal - minVal) <= 1.5) {

        const sorted = [...window._regStabilityBuf].sort((a,b)=>a-b);

        const medianVal = sorted[1];

        const isNewBag = (window._lastCountedVal === null) || (Math.abs(medianVal - window._lastCountedVal) > 4.0);

        if (isNewBag) {

          window._lastCountedVal = medianVal;

          const countBin = (Math.abs(medianVal) <= 7.0) ? '0-7' : ((Math.abs(medianVal) <= 15.0) ? '8-15' : ((Math.abs(medianVal) <= 25.0) ? '16-25' : 'over'));

          recordBagInBin(countBin);

        }

      }

    }

  }

}

