window.getActiveRecipeCamSrc = function(errLevel) {

  const rec = (window.HMI_STATE && window.HMI_STATE.recipe) ? window.HMI_STATE.recipe : null;

  const n = (rec && rec.name ? rec.name : '').toLowerCase();

  let prefix = 'veerashivaji';

  if (n.includes('thangamayil')) prefix = 'thangamayil';

  else if (n.includes('india')) prefix = 'indiagate';

  else if (n.includes('kohinoor')) prefix = 'kohinoor';

  else if (n.includes('royal') || n.includes('bullet')) prefix = 'royal_bullet';



  let suffix = '0mm';

  if (errLevel === '+10mm') suffix = 'plus10mm';

  else if (errLevel === '-10mm') suffix = 'minus10mm';

  const basePath = window.location.protocol.startsWith('http') ? '/images/' : '../images/';

  return `${basePath}${prefix}_front_back_${suffix}.jpg`;

};

