function stopLiveCamera(force = false) {

  if (typeof liveCompareTimer !== 'undefined' && liveCompareTimer) {

    clearInterval(liveCompareTimer);

    liveCompareTimer = null;

  }

  if (typeof liveDisplacementTimer !== 'undefined' && liveDisplacementTimer) {

    clearInterval(liveDisplacementTimer);

    liveDisplacementTimer = null;

  }

  if (window.liveDisplacementTimer) {

    clearInterval(window.liveDisplacementTimer);

    window.liveDisplacementTimer = null;

  }



  // 1. Halt all tracked MediaStreams

  if (window._allMediaStreams) {

    window._allMediaStreams.forEach(s => haltMediaTracks(s));

    window._allMediaStreams.clear();

  }

  if (window.liveMediaStream) {

    haltMediaTracks(window.liveMediaStream);

    window.liveMediaStream = null;

  }

  if (typeof liveMediaStream !== 'undefined' && liveMediaStream) {

    haltMediaTracks(liveMediaStream);

    liveMediaStream = null;

  }



  // 2. Halt tracks attached to any video elements, pause, and detach

  ['home-cam-video', 'full-cam-video', 'recipe-cam-video'].forEach(id => {

    const v = document.getElementById(id);

    if (v) {

      if (v.srcObject) {

        haltMediaTracks(v.srcObject);

        v.srcObject = null;

      }

      try {

        v.pause();

        v.removeAttribute('src');

        v.load();

      } catch(e) {}

      v.style.display = 'none';

    }

  });



  // 3. Clear image fallbacks to abort any MJPEG connections on the home plate

  ['recipe-live-cam-img', 'recipe-cam-stream-fallback'].forEach(id => {

    const img = document.getElementById(id);

    if (img) {

      img.style.display = 'none';

      img.removeAttribute('src');

      img.src = 'data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';

    }

  });



  const offOverlay = document.getElementById('live-cam-off-overlay');

  if (offOverlay) {

    offOverlay.style.display = 'flex';

    offOverlay.style.zIndex = '10';

  }

  const led = document.getElementById('live-cam-led');

  if (led) {

    led.classList.remove('active');

    led.style.background = '#475569';

    led.style.boxShadow = 'none';

  }

  const titleLbl = document.getElementById('live-cam-title-lbl');

  if (titleLbl) titleLbl.style.color = '#64748b';

  const stat = document.getElementById('live-cam-top-stat');

  if (stat) {

    stat.textContent = 'CAMERA OFF';

    stat.style.color = '#64748b';

    stat.style.borderColor = '#1e293b';

    stat.style.background = '#090d14';

  }

  const livePlate = document.getElementById('recipe-live-cam-plate');

  if (livePlate) {

    livePlate.style.cursor = 'pointer';

    livePlate.title = 'Click to open Camera Inspection';

  }

  if (force) {

    try {

      fetch('/api/camera/stop', { method: 'POST' }).catch(()=>{});

    } catch(e){}

  }

}

