window.setLiveCamError = function(err) {

  if (!CAM_CONFIGS[err]) err = 'live';

  activeCamError = err;

  window.activeCamError = err;

  const cfg = CAM_CONFIGS[err] || CAM_CONFIGS['live'];



  // 1. Update all error buttons (both on screen-stn and screen-cam)

  document.querySelectorAll('.error-pill').forEach(btn => {

    const match = btn.getAttribute('data-error') === err;

    btn.classList.toggle('active', match);

