      if (homeVid) homeVid.style.display = 'none';

      const recipeSrc = (typeof window.getActiveRecipeCamSrc === 'function') ? window.getActiveRecipeCamSrc(err) : cfg.src;

      if (img) {

        img.src = recipeSrc;

        img.style.display = 'block';

      }

      if (homeImg) {

