  const regOffset = document.getElementById('cam-reg-offset-val');

  if (regOffset) {

    regOffset.textContent = cfg.offset;

    regOffset.style.color = cfg.offsetColor;

  }



  const confVal = document.getElementById('cam-conf-val');

  if (confVal) {

    confVal.innerHTML = `${cfg.confidence}`;

  }



  const errValEl = document.getElementById('cam-error-pct-val');

  if (errValEl) {

    const errSign = (cfg.errorMm > 0) ? '+' : '';

    errValEl.textContent = (Math.abs(cfg.errorMm) < 0.05) ? '0.0 mm' : `${errSign}${cfg.errorMm.toFixed(1)} mm`;

    errValEl.style.color = (cfg.status === 'IN SPEC') ? '#2ea043' : (cfg.activeZone === '8-15' ? '#d29922' : '#f85149');

  }



  const errBadgeEl = document.getElementById('cam-error-status-badge');

  if (errBadgeEl) {

    errBadgeEl.textContent = cfg.statusBadge;

    const isPass = (cfg.status === 'IN SPEC');

    errBadgeEl.style.color = isPass ? '#2ea043' : (cfg.activeZone === '8-15' ? '#d29922' : '#f85149');

    errBadgeEl.style.background = isPass ? '#0d2217' : (cfg.activeZone === '8-15' ? '#2e2305' : '#2b1012');

    errBadgeEl.style.borderColor = isPass ? '#2ea043' : (cfg.activeZone === '8-15' ? '#d29922' : '#da3633');

  }



  const hudPill = document.getElementById('hud-error-pill');

  if (hudPill) {

    const dyStr = (cfg.errorMm > 0 ? '+' : '') + cfg.errorMm.toFixed(1) + 'mm';

    const isPass = (cfg.status === 'IN SPEC');

    hudPill.textContent = `ALIGNMENT: ${dyStr} • DISTANCE: ${(Math.abs(cfg.errorMm) < 0.05) ? '0.0 mm' : dyStr}`;

    hudPill.style.color = isPass ? '#2ea043' : (cfg.activeZone === '8-15' ? '#d29922' : '#f85149');

    hudPill.style.borderColor = isPass ? '#2ea043' : (cfg.activeZone === '8-15' ? '#d29922' : '#f85149');

  }



  // 4. Update Station 2 Mark Error and Detection Zones

  const isStn2Off = (window.HMI_STATE?.stn2?.mode === 'OFF');

  const rec = window.HMI_STATE && window.HMI_STATE.recipe ? window.HMI_STATE.recipe : { repeatLength: 740 };

  const repeatLen = Number(rec.repeatLength) || 740;

  if (typeof updateRepAndRulerDisplay === 'function') {

    updateRepAndRulerDisplay(repeatLen, cfg.errorMm, !isStn2Off, isStn2Off);

  }



  // Detection Zone Chips

  document.querySelectorAll('.zone-chip').forEach(chip => {

    const z = chip.getAttribute('data-zone');

    if (z === '0-7' || z === '8-15' || z === '16-25') {

      const isActive = (z === cfg.activeZone);

      chip.classList.toggle('active', isActive);

    }

  });



  if (typeof window.fitCamStage === 'function') {

    window.fitCamStage();

  }



  // 5. Notify server of active simulation error and fetch updated comparison data

  try {

    fetch('/api/camera/sim_error', {

      method: 'POST',

      headers: { 'Content-Type': 'application/json' },

      body: JSON.stringify({ error: err })

    }).catch(() => {});



    const activeRid = (window.HMI_STATE && window.HMI_STATE.recipe && window.HMI_STATE.recipe.numericId) ? window.HMI_STATE.recipe.numericId : 0;

    const s2Mode = (window.HMI_STATE?.stn2?.mode || 'AUTO');

    fetch(`/api/camera/compare_front_back?error=${encodeURIComponent(err)}&recipe_id=${activeRid}&mode=${encodeURIComponent(s2Mode)}`)

      .then(r => r.json())

      .then(d => {

        if (d) (window.updateErrorPercentageDisplay || updateErrorPercentageDisplay)(d);

      })

      .catch(() => {});

  } catch(e) {}

};

