window.fitCamStage = function() {

  const container = document.getElementById('cam-preview-container');

  const stage = document.getElementById('cam-stage-wrapper');

  if (!container || !stage) return;

  const cw = container.clientWidth - 8;

  const ch = container.clientHeight - 8;

  if (cw <= 0 || ch <= 0) return;

  const aspect = 860 / 630;

  let w = cw;

  let h = w / aspect;

  if (h > ch) {

    h = ch;

    w = h * aspect;

  }

  const tw = Math.floor(w) + 'px';

  const th = Math.floor(h) + 'px';

  if (stage.style.width !== tw || stage.style.height !== th) {

    stage.style.width = tw;

    stage.style.height = th;

  }

};

