function initLiveCamSwitcher() {

  const container = document.getElementById('cam-preview-container');

  if (container && window.ResizeObserver) {

    new ResizeObserver(() => {

      if (typeof window.fitCamStage === 'function') window.fitCamStage();

    }).observe(container);

  }



  document.addEventListener('click', function(e) {

    const pill = e.target.closest('.error-pill');

    if (pill) {

      const err = pill.getAttribute('data-error');

      if (err) {

        e.preventDefault();

        window.setLiveCamError(err);

      }

    }

  });



  // Clicking live cam plate or header opens camera screen in both MAN and AUTO mode of STN 2

  const openLiveCam = function(e) {

    if (e && e.preventDefault) e.preventDefault();

    const curMode = (window.HMI_STATE?.stn2?.mode || 'OFF');

    window.isCameraUserActive = true;

    document.querySelectorAll('.screen-panel').forEach(p => p.classList.remove('active'));

    document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));

    const s = document.getElementById('screen-cam');

    if (s) {

      s.classList.add('active');

      const modeBadge = document.getElementById('full-cam-mode-badge');

      if (modeBadge) {

        if (curMode === 'AUTO') {

          modeBadge.textContent = 'AUTO LIVE';

          modeBadge.style.color = '#7ee787';

          modeBadge.style.borderColor = '#2ea043';

          modeBadge.style.background = '#0d2217';

        } else if (curMode === 'MAN') {

          modeBadge.textContent = 'MAN LIVE';

          modeBadge.style.color = '#38bdf8';

          modeBadge.style.borderColor = '#38bdf8';

          modeBadge.style.background = '#081d33';

        } else {

          modeBadge.textContent = 'STANDBY LIVE';

          modeBadge.style.color = '#f59e0b';

          modeBadge.style.borderColor = '#d97706';

          modeBadge.style.background = '#261c02';

        }

      }

      requestAnimationFrame(() => {

        if (typeof window.fitCamStage === 'function') window.fitCamStage();

      });

      if (typeof window.startLiveCameraFeed === 'function') {

        window.startLiveCameraFeed(true);

      } else if (typeof window.startLiveCamera === 'function') {

        window.startLiveCamera();

      }

      const chosenErr = window.activeCamError || 'live';

      activeCamError = chosenErr;

      window.activeCamError = chosenErr;

      if (typeof window.setLiveCamError === 'function') {

        window.setLiveCamError(chosenErr);

      } else {

        const preview = document.getElementById('full-cam-preview-img');

        if (preview) preview.src = '/images/veerashivaji_front_back_0mm.jpg';

      }

    }

  };



  const livePlate = document.getElementById('recipe-live-cam-plate');

  if (livePlate) livePlate.addEventListener('click', openLiveCam);



  // Also wire the LIVE CAM header text

  const liveHdr = document.getElementById('live-cam-top-stat');

  if (liveHdr && liveHdr.parentElement) {

    liveHdr.parentElement.style.cursor = 'pointer';

    liveHdr.parentElement.addEventListener('click', openLiveCam);

  }



  // Return to main HMI button from camera inspection screen

  window.startLiveCamera = startLiveCamera;

  window.stopLiveCamera = stopLiveCamera;

  window.startLiveCameraFeed = startLiveCamera;



  const retBtn = document.getElementById('btn-cam-return-home');

  if (retBtn) {

    retBtn.addEventListener('click', function() {

      if (typeof returnToHomeScreen === 'function') {

        returnToHomeScreen();

      } else {

        document.querySelectorAll('.screen-panel').forEach(p => p.classList.remove('active'));

        document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));

        const s = document.getElementById('screen-stn');

        if (s) s.classList.add('active');

        const homeTab = document.querySelector('.nav-tab[data-target="screen-stn"]');

        if (homeTab) homeTab.classList.add('active');

      }

    });

  }



  // Wire Screen 1 SCAN button for image detection and recipe auto-config

  const scanBtn = document.getElementById('btn-scan-trigger');

  if (scanBtn) {

    scanBtn.addEventListener('click', async function(e) {

      e.preventDefault();

      if (window.HMI_STATE && window.HMI_STATE.stn2 && window.HMI_STATE.stn2.mode === 'OFF') {

        if (typeof showToast === 'function') showToast('SCAN NOT AVAILABLE IN OFF MODE', true);

        return;

      }

      const oldContent = scanBtn.innerHTML;

      scanBtn.disabled = true;

      scanBtn.innerHTML = '<span class="status-dot pulsing" style="background:#20e85a;display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:4px;"></span> SCANNING...';

      try {

        fetch('/api/fbarx/cmd', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ cmd: 'SCAN' }) }).catch(() => {});

        const err = window.activeCamError || '0mm';

        const snapRes = await fetch('/api/camera/snapshot?error=' + encodeURIComponent(err));

        let blob = null;

        if (snapRes.ok) blob = await snapRes.blob();



        const activeRid = (window.HMI_STATE && window.HMI_STATE.recipe && window.HMI_STATE.recipe.numericId) ? window.HMI_STATE.recipe.numericId : 0;

        const cmpRes = await fetch('/api/camera/compare?source=hmi_scan&recipe_id=' + activeRid + '&error=' + encodeURIComponent(err), {

          method: 'POST',

          headers: { 'Content-Type': 'image/jpeg' },

          body: blob || undefined

        }).then(r => r.json()).catch(() => null);



        if (cmpRes && cmpRes.front_back && cmpRes.front_back.ok) {

          updateErrorPercentageDisplay(cmpRes.front_back);

        } else if (cmpRes && typeof cmpRes.error_mm === 'number') {

          updateErrorPercentageDisplay(cmpRes);

        }



        if (cmpRes && cmpRes.confidence >= 0.60 && cmpRes.best) {

          const hit = (typeof RecipeDB !== 'undefined' ? RecipeDB.findByName(cmpRes.best) : null) || 

                      (typeof RecipeDB !== 'undefined' && cmpRes.best_recipe_id ? RecipeDB.get(cmpRes.best_recipe_id) : null) || 

                      (typeof RecipeDB !== 'undefined' ? RecipeDB.list().find(r => r.name.toLowerCase() === cmpRes.best.toLowerCase() || String(r.numericId) === String(cmpRes.best_recipe_id)) : null);

          if (hit && typeof applyRecipeToHmi === 'function') {

            applyRecipeToHmi(hit);

            const pct = Math.round(cmpRes.confidence * 100);

            const fbData = cmpRes.front_back || cmpRes;

            const errMmVal = (typeof fbData.offset_y_mm === 'number') 

              ? fbData.offset_y_mm 

              : ((typeof fbData.error_mm === 'number') ? fbData.error_mm : 0.0);

            const errSign = errMmVal > 0 ? '+' : '';

            const binVal = fbData.bin || (Math.abs(errMmVal) <= 7.0 ? '0-7' : '8-15');

            recordBagInBin(binVal, true);

            if (typeof showToast === 'function') showToast(`DETECTED: ${hit.name} (${pct}%) • ERROR: ${errSign}${errMmVal.toFixed(1)}mm — RECIPE APPLIED!`);

          }

        } else {

          if (typeof showToast === 'function') showToast('SCAN COMPLETED — NO RECIPE MATCH (>60%)');

        }

      } catch(err) {

        console.warn('Scan trigger error:', err);

        if (typeof showToast === 'function') showToast('SCAN ERROR: ' + err.message, true);

      } finally {

        scanBtn.disabled = false;

        scanBtn.innerHTML = oldContent;

      }

    });

  }



  // Wire Screen 2 SINGLE FRAME CAPTURE button

  const snapTestBtn = document.getElementById('btn-snap-test');

  if (snapTestBtn) {

    snapTestBtn.addEventListener('click', async function(e) {

      e.preventDefault();

      const oldText = snapTestBtn.textContent;

      snapTestBtn.disabled = true;

      snapTestBtn.textContent = 'CAPTURING & COMPARING...';

      try {

        fetch('/api/fbarx/cmd', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ cmd: 'SCAN' }) }).catch(() => {});

        const err = window.activeCamError || '0mm';

        let blob = null;

        const vid = document.getElementById('full-cam-video');

        if (err === 'live' && vid && vid.style.display !== 'none' && vid.videoWidth > 0) {

          const canvas = document.createElement('canvas');

          canvas.width = Math.min(860, vid.videoWidth);

          canvas.height = Math.round(canvas.width * vid.videoHeight / vid.videoWidth);

          canvas.getContext('2d').drawImage(vid, 0, 0, canvas.width, canvas.height);

          blob = await new Promise(res => canvas.toBlob(res, 'image/jpeg', 0.90));

        } else {

          const snapRes = await fetch('/api/camera/snapshot?error=' + encodeURIComponent(err));

          if (snapRes.ok) blob = await snapRes.blob();

        }



        const activeRid = (window.HMI_STATE && window.HMI_STATE.recipe && window.HMI_STATE.recipe.numericId) ? window.HMI_STATE.recipe.numericId : 0;

        const [cmpRes, fbRes] = await Promise.all([

          fetch('/api/camera/compare?source=screen2_snap&recipe_id=' + activeRid + '&error=' + encodeURIComponent(err), {

            method: 'POST',

            headers: { 'Content-Type': 'image/jpeg' },

            body: blob || undefined

          }).then(r => r.json()).catch(() => null),

          fetch('/api/camera/compare_front_back?error=' + encodeURIComponent(err) + '&recipe_id=' + activeRid, {

            method: 'POST',

            headers: { 'Content-Type': 'image/jpeg' },

            body: blob || undefined

          }).then(r => r.json()).catch(() => null)

        ]);



        if (fbRes && fbRes.ok) {

          updateErrorPercentageDisplay(fbRes);

          recordBagInBin(fbRes.bin || (Math.abs(fbRes.offset_y_mm || 0) <= 7.0 ? '0-7' : '8-15'), true);

        }



        if (cmpRes && cmpRes.confidence >= 0.60 && cmpRes.best) {

          const hit = (typeof RecipeDB !== 'undefined' ? RecipeDB.findByName(cmpRes.best) : null) || 

                      (typeof RecipeDB !== 'undefined' && cmpRes.best_recipe_id ? RecipeDB.get(cmpRes.best_recipe_id) : null) || 

                      (typeof RecipeDB !== 'undefined' ? RecipeDB.list().find(r => r.name.toLowerCase() === cmpRes.best.toLowerCase() || String(r.numericId) === String(cmpRes.best_recipe_id)) : null);

          if (hit) {

            if (typeof applyRecipeToHmi === 'function') applyRecipeToHmi(hit);

            const pct = Math.round(cmpRes.confidence * 100);

            const camMatchedName = document.getElementById('cam-matched-name');

            if (camMatchedName) camMatchedName.textContent = hit.name + ' (Front & Back)';

            const errMmVal = (fbRes && typeof fbRes.error_mm === 'number') 

              ? fbRes.error_mm 

              : ((fbRes && typeof fbRes.reg_err_mm === 'number') ? fbRes.reg_err_mm : 0.0);

            const dyVal = (fbRes && typeof fbRes.offset_y_mm === 'number') ? fbRes.offset_y_mm : errMmVal;

            const errSign = dyVal > 0 ? '+' : '';

            const status = (fbRes && fbRes.status) ? fbRes.status : 'IN SPEC';

            if (typeof showToast === 'function') showToast(`CAPTURED: ${hit.name} • ERROR: ${errSign}${dyVal.toFixed(1)}mm (${status})`);

          }

        } else {

          const errMmVal = (fbRes && typeof fbRes.error_mm === 'number') 

            ? fbRes.error_mm 

            : ((fbRes && typeof fbRes.reg_err_mm === 'number') ? fbRes.reg_err_mm : 0.0);

          const dyVal = (fbRes && typeof fbRes.offset_y_mm === 'number') ? fbRes.offset_y_mm : errMmVal;

          const errSign = dyVal > 0 ? '+' : '';

          if (typeof showToast === 'function') showToast(`CAPTURE DONE • ERROR: ${errSign}${dyVal.toFixed(1)}mm`);

        }

      } catch(err) {

        console.warn('Snap test error:', err);

        if (typeof showToast === 'function') showToast('CAPTURE ERROR: ' + err.message, true);

      } finally {

        snapTestBtn.disabled = false;

        snapTestBtn.textContent = oldText;

      }

    });

  }



  // Wire Camera Line Calibration Modal (11-11-26.md)

  const openCalBtn = document.getElementById('btn-open-cam-cal');

  const calModal = document.getElementById('camera-cal-modal');

  const closeCalBtn = document.getElementById('btn-close-cam-cal');

  const saveRulerBtn = document.getElementById('btn-save-ruler-cal');

  const runZeroBtn = document.getElementById('btn-run-zero-cal');

  const saveAllBtn = document.getElementById('btn-save-all-cam-cal');



  async function loadCameraCalibrationUi() {

    try {

      const res = await fetch('/api/camera/calibration');

      if (res.ok) {

        const cal = await res.json();

        const scaleDisp = document.getElementById('cal-scale-display');

        if (scaleDisp && cal.scale_px_per_mm) scaleDisp.textContent = `${Number(cal.scale_px_per_mm).toFixed(2)} px/mm`;

        const zeroDisp = document.getElementById('cal-zero-display');

        if (zeroDisp && typeof cal.zero_offset_mm === 'number') zeroDisp.textContent = `Offset: ${cal.zero_offset_mm >= 0 ? '+' : ''}${cal.zero_offset_mm.toFixed(2)} mm`;

        const nomInp = document.getElementById('cal-input-nominal-mm');

        if (nomInp && typeof cal.nominal_mm === 'number') nomInp.value = cal.nominal_mm;

        const tolInp = document.getElementById('cal-input-tol-mm');

        if (tolInp && typeof cal.tolerance_mm === 'number') tolInp.value = cal.tolerance_mm;

        const orientSel = document.getElementById('cal-select-orientation');

        if (orientSel && cal.orientation) orientSel.value = cal.orientation;

        const darkSel = document.getElementById('cal-select-dark');

        if (darkSel && typeof cal.dark_line !== 'undefined') darkSel.value = cal.dark_line ? '1' : '0';

        const nomLenInp = document.getElementById('cal-input-nom-length-mm');

        if (nomLenInp && typeof cal.nominal_length_mm === 'number') nomLenInp.value = cal.nominal_length_mm;

        const skewTopInp = document.getElementById('cal-input-nom-skew-top-mm');

        if (skewTopInp && typeof cal.nominal_skew_top_mm === 'number') skewTopInp.value = cal.nominal_skew_top_mm;

        const skewBotInp = document.getElementById('cal-input-nom-skew-bottom-mm');

        if (skewBotInp && typeof cal.nominal_skew_bottom_mm === 'number') skewBotInp.value = cal.nominal_skew_bottom_mm;

        const stat = document.getElementById('cal-feedback-stat');

        if (stat) stat.textContent = `Calibrated for ${cal.calibrated_width || 1600}x${cal.calibrated_height || 1200} px frame.`;

      }

    } catch (e) {

      console.warn('Failed to load camera calibration:', e);

    }

  }



  if (openCalBtn && calModal) {

    openCalBtn.addEventListener('click', () => {

      loadCameraCalibrationUi();

      calModal.classList.add('open');

      calModal.style.display = 'flex';

    });

  }



  if (closeCalBtn && calModal) {

    closeCalBtn.addEventListener('click', () => {

      calModal.classList.remove('open');

      calModal.style.display = 'none';

    });

  }



  if (saveRulerBtn) {

    saveRulerBtn.addEventListener('click', async () => {

      const knownMm = parseFloat(document.getElementById('cal-input-known-mm')?.value || '50.0');

      const distPx = parseFloat(document.getElementById('cal-input-dist-px')?.value || '200.0');

      if (knownMm <= 0 || distPx <= 0) {

        if (typeof showToast === 'function') showToast('ENTER POSITIVE RULER LENGTH AND PIXEL DISTANCE', true);

        return;

      }

      try {

        const res = await fetch('/api/camera/calibrate_ruler', {

          method: 'POST',

          headers: { 'Content-Type': 'application/json' },

          body: JSON.stringify({ known_mm: knownMm, distance_px: distPx })

        });

        const d = await res.json();

        if (d && d.ok) {

          document.getElementById('cal-scale-display').textContent = `${Number(d.scale_px_per_mm).toFixed(2)} px/mm`;

          if (typeof showToast === 'function') showToast(`SCALE CALIBRATED: ${Number(d.scale_px_per_mm).toFixed(2)} px/mm`);

        } else {

          if (typeof showToast === 'function') showToast('RULER CALIBRATION FAILED: ' + (d.error || 'Unknown'), true);

        }

      } catch (e) {

        if (typeof showToast === 'function') showToast('CALIBRATION REQUEST FAILED', true);

      }

    });

  }



  if (runZeroBtn) {

    runZeroBtn.addEventListener('click', async () => {

      const nomMm = parseFloat(document.getElementById('cal-input-nominal-mm')?.value || '0.0');

      const err = window.activeCamError || 'live';

      const activeRid = (window.HMI_STATE && window.HMI_STATE.recipe && window.HMI_STATE.recipe.numericId) ? window.HMI_STATE.recipe.numericId : 0;

      try {

        const res = await fetch(`/api/camera/calibrate_zero?error=${encodeURIComponent(err)}&recipe_id=${activeRid}`, {

          method: 'POST',

          headers: { 'Content-Type': 'application/json' },

          body: JSON.stringify({ nominal_mm: nomMm })

        });

        const d = await res.json();

        if (d && d.ok) {

          const zOff = Number(d.zero_offset_mm || 0);

          document.getElementById('cal-zero-display').textContent = `Offset: ${zOff >= 0 ? '+' : ''}${zOff.toFixed(2)} mm`;

          if (typeof showToast === 'function') showToast(`MASTER ZERO STORED: ${zOff >= 0 ? '+' : ''}${zOff.toFixed(2)} mm`);

        } else {

          if (typeof showToast === 'function') showToast('ZERO CALIBRATION FAILED', true);

        }

      } catch (e) {

        if (typeof showToast === 'function') showToast('ZERO CALIBRATION ERROR', true);

      }

    });

  }



  if (saveAllBtn && calModal) {

    saveAllBtn.addEventListener('click', async () => {

      const payload = {

        nominal_mm: parseFloat(document.getElementById('cal-input-nominal-mm')?.value || '0.0'),

        tolerance_mm: parseFloat(document.getElementById('cal-input-tol-mm')?.value || '7.0'),

        orientation: document.getElementById('cal-select-orientation')?.value || 'vertical',

        dark_line: (document.getElementById('cal-select-dark')?.value === '1'),

        nominal_length_mm: parseFloat(document.getElementById('cal-input-nom-length-mm')?.value || '740.0'),

        nominal_skew_top_mm: parseFloat(document.getElementById('cal-input-nom-skew-top-mm')?.value || '0.0'),

        nominal_skew_bottom_mm: parseFloat(document.getElementById('cal-input-nom-skew-bottom-mm')?.value || '0.0')

      };

      try {

        const res = await fetch('/api/camera/calibration', {

          method: 'POST',

          headers: { 'Content-Type': 'application/json' },

          body: JSON.stringify(payload)

        });

        const d = await res.json();

        if (d && d.ok) {

          if (typeof showToast === 'function') showToast('CAMERA CALIBRATION SAVED SUCCESSFULLY!');

          calModal.classList.remove('open');

          calModal.style.display = 'none';

        }

      } catch (e) {

        if (typeof showToast === 'function') showToast('FAILED TO SAVE CALIBRATION', true);

      }

    });

  }



  if (typeof window.updateZoneCountersDisplay === 'function') {

    window.updateZoneCountersDisplay();

  }



  // User requirement: When page reloads, turn off the camera completely

  if (typeof window.stopLiveCamera === 'function') {

    window.stopLiveCamera(true);

  }

}

