function renderLiveAmmeter(station){

  const state=(window.HMI_STATE&&window.HMI_STATE[station])||(typeof HMI_STATE!=='undefined'&&HMI_STATE[station]);

  if(!state)return;

  const isOff = (state.mode === 'OFF');

  let raw = Number(state.ammeter);

  if (!Number.isFinite(raw)) {

    raw = isOff ? 0.0 : 1.8;

  }

  const value = Math.max(0, Math.min(5, raw));

  const needle=document.querySelector('[data-live-needle="'+station+'"]');

  const valueEl=document.querySelector('[data-live-value="'+station+'"]');

  const segments=document.querySelector('[data-live-segments="'+station+'"]');

  if(needle){

    needle.removeAttribute('transform');

    needle.style.transform='none';

    const frac=value/5.0;

    const angleRad=frac*Math.PI;

    const R=47.0;

    const x2=74.0-R*Math.cos(angleRad);

    const y2=70.0-R*Math.sin(angleRad);

    const line=needle.querySelector('line')||needle;

    line.setAttribute('x1','74');

    line.setAttribute('y1','70');

    line.setAttribute('x2',x2.toFixed(1));

    line.setAttribute('y2',y2.toFixed(1));

  }

  if(valueEl)valueEl.textContent=value.toFixed(1);

  if(segments)[...segments.children].forEach((el,i)=>el.classList.toggle('on',i<Math.round(value/5*segments.children.length)));

}
